package com.nextunlocks;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.Value;
import net.runelite.api.Experience;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

/**
 * What's one requirement away: quests and diaries short of a single skill level, and unlocks the player has the
 * level for that only wait on a quest.
 */
@Value
class AlmostThere
{
	static final AlmostThere NONE = new AlmostThere(Collections.emptyList(), Collections.emptyList());
	private static final Map<Integer, Quest> QUESTS = new HashMap<>();

	static
	{
		for (Quest quest : Quest.values())
		{
			QUESTS.put(quest.getId(), quest);
		}
	}

	/** A quest or diary needing one more skill level. */
	@Value
	static class OneLevelShort
	{
		Unlock.Type type;
		/** The quest or diary, as its wiki title. */
		String title;
		Skill skill;
		int level;
		long xpToGo;
	}

	/** Unlocks the player has the level for, waiting on one quest. */
	@Value
	static class QuestWait
	{
		String quest;
		/** Skill of each unlock, in the same order. */
		List<Skill> skills;
		List<Unlock> unlocks;
	}

	/** Closest first. */
	List<OneLevelShort> oneLevelShort;
	/** Most unlocks first. */
	List<QuestWait> questWaits;

	static AlmostThere of(UnlockRepository repository, Snapshot snapshot)
	{
		if (!snapshot.isLoggedIn())
		{
			return NONE;
		}
		return new AlmostThere(oneLevelShort(repository, snapshot), questWaits(repository, snapshot));
	}

	private static List<OneLevelShort> oneLevelShort(UnlockRepository repository, Snapshot snapshot)
	{
		// every skill's quest and diary entries, gathered per quest or diary
		Map<String, Map<Skill, Integer>> requirements = new LinkedHashMap<>();
		Map<String, Unlock.Type> types = new HashMap<>();
		for (Skill skill : Skills.STATS_TAB.keySet())
		{
			for (Unlock u : repository.all(skill))
			{
				if (u.getType() == Unlock.Type.UNLOCK || !snapshot.getFilter().test(u))
				{
					continue;
				}
				String title = u.getWiki() != null ? u.getWiki() : u.getText();
				requirements.computeIfAbsent(title, t -> new EnumMap<>(Skill.class)).merge(skill, u.getLevel(), Math::max);
				types.put(title, u.getType());
			}
		}

		List<OneLevelShort> result = new ArrayList<>();
		for (Map.Entry<String, Map<Skill, Integer>> e : requirements.entrySet())
		{
			String title = e.getKey();
			if (types.get(title) == Unlock.Type.QUEST && snapshot.getFinishedQuests().contains(title))
			{
				continue;
			}
			Skill missing = null;
			int count = 0;
			for (Map.Entry<Skill, Integer> req : e.getValue().entrySet())
			{
				if (snapshot.effectiveLevel(req.getKey()) < req.getValue())
				{
					missing = req.getKey();
					count++;
				}
			}
			// a quest or diary with every level met is done or only waiting on things this plugin can't see
			if (count == 1)
			{
				int level = e.getValue().get(missing);
				long xp = Math.max(0, Experience.getXpForLevel(level) - snapshot.xp(missing));
				result.add(new OneLevelShort(types.get(title), title, missing, level, xp));
			}
		}
		result.sort(Comparator.comparingLong(OneLevelShort::getXpToGo));
		return result;
	}

	private static List<QuestWait> questWaits(UnlockRepository repository, Snapshot snapshot)
	{
		Map<Integer, QuestWait> waits = new LinkedHashMap<>();
		for (Skill skill : Skills.STATS_TAB.keySet())
		{
			for (Unlock u : repository.all(skill))
			{
				Integer quest = u.getQuest();
				if (quest == null || !snapshot.getQuestsToDo().contains(quest) || !snapshot.shown(skill).test(u))
				{
					continue;
				}
				int level = UnlockRepository.boostable(skill, u) ? snapshot.effectiveLevel(skill) : snapshot.level(skill);
				if (u.getLevel() > level)
				{
					continue;
				}
				QuestWait wait = waits.computeIfAbsent(quest, id -> new QuestWait(questName(id), new ArrayList<>(), new ArrayList<>()));
				wait.skills.add(skill);
				wait.unlocks.add(u);
			}
		}
		List<QuestWait> result = new ArrayList<>(waits.values());
		result.sort(Comparator.comparingInt((QuestWait w) -> -w.unlocks.size()).thenComparing(QuestWait::getQuest));
		return result;
	}

	static String questName(int id)
	{
		Quest quest = QUESTS.get(id);
		return quest == null ? "Quest " + id : quest.getName();
	}
}

package com.nextunlocks;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.List;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/** A pinned quest or diary card's heading: its tab icon, then its name in a bigger font, wrapped to the card's width. */
class CardHeader implements LayoutableRenderableEntity
{
	private static final int GAP = 4;

	/** Null for none. */
	private final BufferedImage icon;
	private final String text;
	private final Color color;
	private final Font font;
	private final double scale;
	private final CardTheme theme;
	private final Rectangle bounds = new Rectangle();
	private Point preferredLocation = new Point();
	private Dimension preferredSize = new Dimension();
	/** The blurred title behind it, kept until the width changes. */
	private BufferedImage glow;
	private int glowWidth;

	CardHeader(BufferedImage icon, String text, Color color, Font font, double scale, CardTheme theme)
	{
		this.theme = theme;
		this.icon = icon;
		this.text = text;
		this.color = color;
		this.font = font;
		this.scale = scale;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		int iconWidth = icon == null ? 0 : (int) Math.round(icon.getWidth() * scale);
		int iconHeight = icon == null ? 0 : (int) Math.round(icon.getHeight() * scale);
		int textX = iconWidth == 0 ? 0 : iconWidth + GAP;

		Font previous = graphics.getFont();
		Object aa = graphics.getRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING);
		graphics.setFont(font);
		if (theme.smooth())
		{
			graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		}
		FontMetrics metrics = graphics.getFontMetrics();
		List<String> lines = CardLine.wrap(metrics, text, Math.max(1, preferredSize.width - textX));
		int lineHeight = metrics.getHeight();
		int textHeight = lines.size() * lineHeight;
		int height = Math.max(iconHeight, textHeight);

		int x = preferredLocation.x;
		int y = preferredLocation.y;
		if (icon != null)
		{
			graphics.drawImage(icon, x, y + (height - iconHeight) / 2, iconWidth, iconHeight, null);
		}
		int top = (height - textHeight) / 2 + metrics.getAscent();
		if (theme.isGlowText() && theme.getGlow() != null)
		{
			if (glow == null || glowWidth != preferredSize.width)
			{
				int width = Math.max(1, preferredSize.width - textX);
				glow = Glow.paint(width, height, theme.getGlowSize(), g ->
				{
					g.setFont(font);
					g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
					g.setColor(theme.getGlow());
					for (int[] o : new int[][]{{0, 0}, {1, 0}, {-1, 0}, {0, 1}, {0, -1}})
					{
						paint(g, lines, o[0], top + o[1], lineHeight);
					}
				});
				glowWidth = preferredSize.width;
			}
			int pad = Glow.pad(theme.getGlowSize());
			graphics.drawImage(glow, x + textX - pad, y - pad, null);
		}
		Color old = graphics.getColor();
		if (theme.isShadow())
		{
			graphics.setColor(Color.BLACK);
			paint(graphics, lines, x + textX + 1, y + top + 1, lineHeight);
		}
		graphics.setColor(color);
		paint(graphics, lines, x + textX, y + top, lineHeight);
		graphics.setColor(old);
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, aa);
		graphics.setFont(previous);

		bounds.setLocation(preferredLocation);
		bounds.setSize(preferredSize.width, height);
		return bounds.getSize();
	}

	private static void paint(Graphics2D graphics, List<String> lines, int x, int baseline, int lineHeight)
	{
		for (String line : lines)
		{
			graphics.drawString(line, x, baseline);
			baseline += lineHeight;
		}
	}

	@Override
	public Rectangle getBounds()
	{
		return bounds;
	}

	@Override
	public void setPreferredLocation(Point position)
	{
		preferredLocation = position;
	}

	@Override
	public void setPreferredSize(Dimension dimension)
	{
		preferredSize = dimension;
	}
}

package com.nextunlocks;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import lombok.Getter;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/**
 * A line of a card, laid out like RuneLite's LineComponent: text on the left, text on the right. Each side is made of
 * parts with their own color, so "XP:" and the number after it can differ, and the theme decides shadow and glow.
 */
class CardLine implements LayoutableRenderableEntity
{
	/** Room kept between the two sides. */
	private static final int GAP = 4;

	private static final class Part
	{
		private String text;
		private final Color color;

		private Part(String text, Color color)
		{
			this.text = text;
			this.color = color;
		}
	}

	private final CardTheme theme;
	private final Font font;
	/** The card's title line, which a theme's header band goes behind. */
	@Getter
	private final boolean header;
	private final List<Part> left = new ArrayList<>();
	private final List<Part> right = new ArrayList<>();
	private Point location = new Point();
	private Dimension preferred = new Dimension();
	private final Rectangle bounds = new Rectangle();

	/** The blurred text behind the line, kept until the text or width changes. */
	private BufferedImage glow;
	private String glowKey;

	CardLine(CardTheme theme, Font font)
	{
		this(theme, font, false);
	}

	CardLine(CardTheme theme, Font font, boolean header)
	{
		this.theme = theme;
		this.font = font;
		this.header = header;
	}

	CardLine left(String text, Color color)
	{
		left.add(new Part(text, color));
		return this;
	}

	CardLine right(String text, Color color)
	{
		right.add(new Part(text, color));
		return this;
	}

	/** Change the text of a right-hand part, by its place among them. */
	void setRight(int index, String text)
	{
		right.get(index).text = text;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Font previous = graphics.getFont();
		Object aa = graphics.getRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING);
		graphics.setFont(font);
		if (theme.smooth())
		{
			graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		}
		FontMetrics metrics = graphics.getFontMetrics();
		int lineHeight = metrics.getHeight();
		int width = preferred.width;
		int rightWidth = width(metrics, right);
		int room = right.isEmpty() ? width : width - rightWidth - GAP;

		// a single long left part wraps, like the game's tooltips; the right side stays on the first line
		List<String> wrapped = null;
		if (left.size() == 1 && width(metrics, left) > room)
		{
			wrapped = wrap(metrics, left.get(0).text, Math.max(1, room));
		}
		int lines = wrapped == null ? 1 : wrapped.size();
		int height = lines * lineHeight;
		int x = location.x;
		int baseline = location.y + lineHeight;

		if (theme.isGlowText() && theme.getGlow() != null)
		{
			String key = width + "|" + text(left) + "|" + text(right) + "|" + (wrapped == null ? "" : String.join("\n", wrapped));
			if (glow == null || !key.equals(glowKey))
			{
				List<String> lefts = wrapped;
				glow = Glow.paint(width, height, theme.getGlowSize(), g ->
				{
					g.setFont(font);
					g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
					// a few copies a pixel apart, so the blur has enough to spread
					for (int[] o : new int[][]{{0, 0}, {1, 0}, {-1, 0}, {0, 1}, {0, -1}})
					{
						paintText(g, metrics, lefts, o[0], lineHeight + o[1], width, rightWidth, theme.getGlow());
					}
				});
				glowKey = key;
			}
			int pad = Glow.pad(theme.getGlowSize());
			graphics.drawImage(glow, x - pad, location.y - pad, null);
		}

		Color color = graphics.getColor();
		if (theme.isShadow())
		{
			paintText(graphics, metrics, wrapped, x + 1, baseline + 1, width, rightWidth, Color.BLACK);
		}
		paintText(graphics, metrics, wrapped, x, baseline, width, rightWidth, null);
		graphics.setColor(color);
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, aa);
		graphics.setFont(previous);

		bounds.setLocation(location);
		bounds.setSize(width, height);
		return new Dimension(width, height);
	}

	/** Both sides, from a baseline, in each part's color or all in one when a color is given. */
	private void paintText(Graphics2D g, FontMetrics metrics, List<String> wrapped, int x, int baseline, int width, int rightWidth,
		Color only)
	{
		if (only != null)
		{
			g.setColor(only);
		}
		if (wrapped != null)
		{
			Color c = left.get(0).color;
			int y = baseline;
			for (String line : wrapped)
			{
				if (only == null)
				{
					g.setColor(c);
				}
				g.drawString(line, x, y);
				y += metrics.getHeight();
			}
		}
		else
		{
			paintParts(g, metrics, left, x, baseline, only);
		}
		paintParts(g, metrics, right, x + width - rightWidth, baseline, only);
	}

	private static void paintParts(Graphics2D g, FontMetrics metrics, List<Part> parts, int x, int baseline, Color only)
	{
		for (Part part : parts)
		{
			if (only == null && part.color != null)
			{
				g.setColor(part.color);
			}
			g.drawString(part.text, x, baseline);
			x += metrics.stringWidth(part.text);
		}
	}

	private static int width(FontMetrics metrics, List<Part> parts)
	{
		int width = 0;
		for (Part part : parts)
		{
			width += metrics.stringWidth(part.text);
		}
		return width;
	}

	private static String text(List<Part> parts)
	{
		StringBuilder text = new StringBuilder();
		for (Part part : parts)
		{
			text.append(part.text).append('\u0000');
		}
		return text.toString();
	}

	/** Words into lines no wider than the width; a word wider than that gets a line of its own. */
	static List<String> wrap(FontMetrics metrics, String text, int width)
	{
		List<String> lines = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : text.split(" "))
		{
			String next = line.length() == 0 ? word : line + " " + word;
			if (line.length() > 0 && metrics.stringWidth(next) > width)
			{
				lines.add(line.toString());
				line = new StringBuilder(word);
			}
			else
			{
				line = new StringBuilder(next);
			}
		}
		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		return lines;
	}

	@Override
	public Rectangle getBounds()
	{
		return bounds;
	}

	@Override
	public void setPreferredLocation(Point position)
	{
		location = position;
	}

	@Override
	public void setPreferredSize(Dimension dimension)
	{
		preferred = dimension;
	}
}

package com.nextunlocks;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/**
 * The line under an item goal's making level saying what the level is for: a tiny icon of the material, then its name
 * in smaller text, cut short with an ellipsis rather than wrapped.
 */
class CardMaterial implements LayoutableRenderableEntity
{
	private static final int INDENT = 6;
	private static final int GAP = 3;
	private static final String ELLIPSIS = "...";

	private final CardTheme theme;
	private final Font font;
	/** Null for none; an item image can still be loading, and is drawn as it is when painted. */
	private final BufferedImage icon;
	private final String text;
	private final Color color;
	private Point location = new Point();
	private Dimension preferred = new Dimension();
	private final Rectangle bounds = new Rectangle();
	/** The blurred text behind it, kept until the width changes. */
	private BufferedImage glow;
	private int glowWidth;

	CardMaterial(CardTheme theme, Font font, BufferedImage icon, String text, Color color)
	{
		this.theme = theme;
		this.font = font;
		this.icon = icon;
		this.text = text;
		this.color = color;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Font previous = graphics.getFont();
		Object aa = graphics.getRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING);
		Object interpolation = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		graphics.setFont(font);
		if (theme.smooth())
		{
			graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		}
		FontMetrics metrics = graphics.getFontMetrics();
		int height = metrics.getHeight();
		int x = location.x + INDENT;
		int width = preferred.width;

		// the icon as tall as the text, keeping the item picture's shape
		int iconHeight = icon == null || icon.getHeight() <= 0 ? 0 : height;
		int iconWidth = iconHeight == 0 ? 0 : Math.max(1, icon.getWidth() * iconHeight / icon.getHeight());
		if (iconWidth > 0)
		{
			graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			graphics.drawImage(icon, x, location.y, iconWidth, iconHeight, null);
			if (interpolation != null)
			{
				graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, interpolation);
			}
			x += iconWidth + GAP;
		}
		int room = Math.max(1, location.x + width - x);
		String shown = fit(metrics, text, room);
		int baseline = location.y + (height + metrics.getAscent() - metrics.getDescent()) / 2;

		if (theme.isGlowText() && theme.getGlow() != null)
		{
			if (glow == null || glowWidth != width)
			{
				glow = Glow.paint(room, height, theme.getGlowSize(), g ->
				{
					g.setFont(font);
					g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
					g.setColor(theme.getGlow());
					g.drawString(shown, 0, baseline - location.y);
				});
				glowWidth = width;
			}
			int pad = Glow.pad(theme.getGlowSize());
			graphics.drawImage(glow, x - pad, location.y - pad, null);
		}
		Color old = graphics.getColor();
		if (theme.isShadow())
		{
			graphics.setColor(Color.BLACK);
			graphics.drawString(shown, x + 1, baseline + 1);
		}
		graphics.setColor(color);
		graphics.drawString(shown, x, baseline);
		graphics.setColor(old);
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, aa);
		graphics.setFont(previous);

		bounds.setLocation(location);
		bounds.setSize(width, height);
		return new Dimension(width, height);
	}

	/** The text, or as much of it as fits with an ellipsis after it. */
	static String fit(FontMetrics metrics, String text, int width)
	{
		if (metrics.stringWidth(text) <= width)
		{
			return text;
		}
		int end = text.length();
		while (end > 0 && metrics.stringWidth(text.substring(0, end).trim() + ELLIPSIS) > width)
		{
			end--;
		}
		return text.substring(0, end).trim() + ELLIPSIS;
	}

	@Override
	public Rectangle getBounds()
	{
		return bounds;
	}

	@Override
	public void setPreferredLocation(Point position)
	{
		location = position;
	}

	@Override
	public void setPreferredSize(Dimension dimension)
	{
		preferred = dimension;
	}
}

package com.nextunlocks;

import java.awt.Color;
import java.awt.Font;
import java.awt.font.FontRenderContext;
import lombok.Builder;
import lombok.Value;
import net.runelite.client.ui.FontManager;

/**
 * How a card looks: its frame, font, bar and the color of every word and number on it. The skills-tab tooltip is
 * always {@link #classic}; pinned cards use the style picked in the config, with the player's changes on top.
 */
@Value
@Builder(toBuilder = true)
class CardTheme
{
	enum Frame
	{
		/** RuneLite's own overlay box, with its lighter edge. */
		CLASSIC,
		FLAT,
		/** An outer and an inner border, like an arcade cabinet's screen. */
		DOUBLE,
		/** Raised grey edges, like an old desktop window. */
		BEVEL,
		ROUNDED,
	}

	private static final Color[] GREENS = {
		new Color(51, 255, 102), new Color(160, 255, 170), new Color(30, 190, 80), Color.WHITE,
	};
	private static final Color[] HANDHELD = {
		new Color(15, 56, 15), new Color(48, 98, 48), new Color(139, 172, 15), new Color(155, 188, 15),
	};

	Frame frame;
	Color background;
	/** Null for none. */
	Color border;
	/** Inside the border on a double frame; null for none. */
	Color innerBorder;
	/** A title bar behind the card's first line, null for none. */
	Color headerBand;
	int corner;
	/** Space between the frame and the content. */
	int padding;
	/** The background ignores the opacity setting, for looks that only work solid. */
	boolean opaque;
	boolean scanlines;
	boolean shadow;
	NextUnlocksConfig.CardFont font;
	NextUnlocksConfig.BarStyle bar;
	/** Whether a reached unlock holds the bar at 100% and level-ups burst into pixels. */
	boolean levelUp;
	/** The burst's colors; null for a rainbow. */
	Color[] burst;
	/** Null for no glow. */
	Color glow;
	boolean glowBorder;
	boolean glowText;
	int glowSize;

	Color skillName;
	Color levelLabel;
	Color levelValue;
	Color xpLabel;
	Color xpValue;
	Color nextLevelLabel;
	Color nextLevelValue;
	Color remainingLabel;
	Color remainingValue;
	Color nextUnlockLabel;
	Color nextUnlockLevel;
	Color nextUnlockXp;
	Color unlock;
	Color locked;
	Color more;
	/** Null for the skill's own color. */
	Color goalLabel;
	/** Null for the skill's own color. */
	Color goalLevel;
	Color goalXp;
	Color taskTitle;
	Color met;
