	/** Every text color from three: labels, values, and the accent for names and the next unlock. */
	private static CardThemeBuilder colors(Color label, Color value, Color accent, Palette palette)
	{
		return builder()
			.skillName(accent)
			.levelLabel(value)
			.levelValue(value)
			.xpLabel(label)
			.xpValue(value)
			.nextLevelLabel(label)
			.nextLevelValue(value)
			.remainingLabel(label)
			.remainingValue(value)
			.nextUnlockLabel(accent)
			.nextUnlockLevel(accent)
			.nextUnlockXp(value)
			.unlock(value)
			.locked(palette.getLocked())
			.more(Color.LIGHT_GRAY)
			.goalXp(value)
			.taskTitle(accent)
			.met(Color.GREEN)
			.unmet(Color.RED)
			.barFill(palette.getProgress())
			.barBackground(palette.getProgressBackground())
			.barText(Color.WHITE);
	}

	/** Whether the font is a smooth desktop one, which wants antialiasing, rather than the game's pixel fonts. */
	boolean smooth()
	{
		return font == NextUnlocksConfig.CardFont.SANS || font == NextUnlocksConfig.CardFont.SANS_BOLD
			|| font == NextUnlocksConfig.CardFont.MONO;
	}

	/** How much wider this theme's text runs than the game font's, so cards can grow to fit; never less than 1. */
	double widthScale(int textSize)
	{
		String sample = "Next unlock: 99 1,234,567 xp";
		FontRenderContext context = new FontRenderContext(null, smooth(), false);
		Font game = FontManager.getRunescapeFont().deriveFont((float) textSize);
		return Math.max(1, font(textSize).getStringBounds(sample, context).getWidth() / game.getStringBounds(sample, context).getWidth());
	}

	/** The text font, for a text size in the game font's points. */
	Font font(int textSize)
	{
		switch (font)
		{
			case RUNESCAPE_BOLD:
				return FontManager.getRunescapeBoldFont().deriveFont((float) textSize);
			case RUNESCAPE_SMALL:
				return FontManager.getRunescapeSmallFont().deriveFont((float) textSize);
			case SANS:
				return desktop(Font.SANS_SERIF, Font.PLAIN, textSize);
			case SANS_BOLD:
				return desktop(Font.SANS_SERIF, Font.BOLD, textSize);
			case MONO:
				return desktop(Font.MONOSPACED, Font.PLAIN, textSize);
			default:
				Font regular = FontManager.getRunescapeFont();
				return textSize == regular.getSize() ? regular : regular.deriveFont((float) textSize);
		}
	}

	/** The bold font for quest and diary names, grown by some points. */
	Font titleFont(int textSize, int growth)
	{
		switch (font)
		{
			case SANS:
			case SANS_BOLD:
				return desktop(Font.SANS_SERIF, Font.BOLD, textSize + growth);
			case MONO:
				return desktop(Font.MONOSPACED, Font.BOLD, textSize + growth);
			default:
				Font bold = FontManager.getRunescapeBoldFont();
				return bold.deriveFont((float) Math.round(bold.getSize2D() * textSize / FontManager.getRunescapeFont().getSize() + growth));
		}
	}

	/** Desktop fonts look bigger than the game's at the same size. */
	private static Font desktop(String name, int style, int textSize)
	{
		return new Font(name, style, 1).deriveFont((float) Math.round(textSize * 0.78f));
	}
}

package com.nextunlocks;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.awt.image.ConvolveOp;
import java.awt.image.Kernel;
import java.util.Arrays;
import java.util.function.Consumer;

/** Soft glows: something painted once, blurred, then drawn behind the real thing. Callers keep the image until it changes. */
final class Glow
{
	private Glow()
	{
	}

	/** Space around the painted area the glow can spread into. */
	static int pad(int radius)
	{
		return radius * 2;
	}

	/**
	 * Paint into an image the size of the area plus the pad on every side, then blur it. The painter's origin is the
	 * area's corner, so the image goes at the area's corner minus the pad.
	 */
	static BufferedImage paint(int width, int height, int radius, Consumer<Graphics2D> painter)
	{
		int pad = pad(radius);
		// premultiplied, so blurring into the transparent edge doesn't darken the color
		BufferedImage image = new BufferedImage(width + pad * 2, height + pad * 2, BufferedImage.TYPE_INT_ARGB_PRE);
		Graphics2D g = image.createGraphics();
		g.translate(pad, pad);
		painter.accept(g);
		g.dispose();
		// a box blur twice in each direction is close to a gaussian
		for (int pass = 0; pass < 2; pass++)
		{
			image = blur(image, radius, true);
			image = blur(image, radius, false);
		}
		return image;
	}

	private static BufferedImage blur(BufferedImage image, int radius, boolean horizontal)
	{
		int size = radius * 2 + 1;
		float[] weights = new float[size];
		Arrays.fill(weights, 1f / size);
		Kernel kernel = horizontal ? new Kernel(size, 1, weights) : new Kernel(1, size, weights);
		BufferedImage out = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_ARGB_PRE);
		return new ConvolveOp(kernel, ConvolveOp.EDGE_NO_OP, null).filter(image, out);
	}
}

package com.nextunlocks;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.stream.Collectors;
import lombok.Value;
import net.runelite.api.Skill;

/** An unlock the player has set as a goal, kept by skill, level and text so it survives a data reload. */
@Value
class Goal
{
	private static final String FIELD = "|";
	private static final String SEPARATOR = "\n";

	Skill skill;
	int level;
	String text;

	static Goal of(Skill skill, Unlock u)
	{
		return new Goal(skill, u.getLevel(), u.getText());
	}

	/** A goal of just reaching a level. */
	static Goal level(Skill skill, int level)
	{
		return new Goal(skill, level, "Level " + level);
	}

	boolean is(Skill skill, Unlock u)
	{
		return this.skill == skill && level == u.getLevel() && text.equals(u.getText());
	}

	/** Goals from the config string; entries that can't be read are skipped. */
	static List<Goal> parse(String config)
	{
		List<Goal> goals = new ArrayList<>();
		for (String line : config.split(SEPARATOR))
		{
			String[] parts = line.split("\\" + FIELD, 3);
			if (parts.length < 3)
			{
				continue;
			}
			try
			{
				goals.add(new Goal(Skill.valueOf(parts[0].trim()), Integer.parseInt(parts[1].trim()), parts[2]));
			}
			catch (IllegalArgumentException ignored)
			{
				// a skill that no longer exists, or a mangled level
			}
		}
		return goals;
	}

	static String format(Collection<Goal> goals)
	{
		return goals.stream()
			.map(g -> g.skill.name() + FIELD + g.level + FIELD + g.text)
			.collect(Collectors.joining(SEPARATOR));
	}
}

package com.nextunlocks;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.text.NumberFormat;
import java.util.function.ToIntFunction;
import lombok.Getter;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;

/** XP left to a goal. Rendered on the client thread. */
class GoalInfoBox extends InfoBox
{
	@Getter
	private final Goal goal;
	private final ToIntFunction<Skill> xp;
	private final Color color;

	GoalInfoBox(BufferedImage image, Plugin plugin, Goal goal, ToIntFunction<Skill> xp, Color color)
	{
		super(image, plugin);
		this.goal = goal;
		this.xp = xp;
		this.color = color;
	}

	/** Room for the box's text under the icon, so the xp isn't drawn over it. */
	private static final int SIZE = 32;
	private static final int ICON_HEIGHT = 21;

	/**
	 * The icon shrunk into the top of a square, with the bottom left empty: infoboxes draw their text at the
	 * bottom, so it sits under the icon instead of on it.
	 */
	static BufferedImage withTextRoom(BufferedImage icon)
	{
		BufferedImage out = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
		if (icon == null || icon.getWidth() <= 0 || icon.getHeight() <= 0)
		{
			return out;
		}
		double scale = Math.min(1, Math.min((double) SIZE / icon.getWidth(), (double) ICON_HEIGHT / icon.getHeight()));
		int w = Math.max(1, (int) Math.round(icon.getWidth() * scale));
		int h = Math.max(1, (int) Math.round(icon.getHeight() * scale));
		Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(icon, (SIZE - w) / 2, (ICON_HEIGHT - h) / 2, w, h, null);
		g.dispose();
		return out;
	}

	private long xpToGo()
	{
		return Math.max(0, Experience.getXpForLevel(goal.getLevel()) - xp.applyAsInt(goal.getSkill()));
	}

	@Override
	public String getText()
	{
		return NextUnlocksPanel.shortXp(xpToGo());
	}

	@Override
	public Color getTextColor()
	{
		return color;
	}

	@Override
	public String getTooltip()
	{
		return "Goal: " + goal.getText() + "</br>" + goal.getSkill().getName() + " " + goal.getLevel() + " - "
			+ NumberFormat.getIntegerInstance().format(xpToGo()) + " xp to go";
	}
}

package com.nextunlocks;

import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import lombok.Getter;
import net.runelite.api.Skill;

/**
 * An item the game's skill guide lists, with every level its entries need: the guide keeps all of an entry's skills,
 * even the ones it only shows under another skill, so this is the game's own list of what the item needs.
 */
@Getter
class GuideItem
{
	/** Skills whose guide levels are for wielding or wearing, not making. */
	private static final Set<Skill> COMBAT = EnumSet.of(Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.RANGED,
		Skill.MAGIC, Skill.PRAYER, Skill.HITPOINTS);
	/** Guide sections of things to equip or use, like Woodcutting's axes. */
	private static final Pattern EQUIPMENT = Pattern.compile("(?i)weapon|armou?r|equipment|tool|axe|harpoon|outfit|cape|staff|staves|ammunition|shield|helm|boots|gloves");

	private final String name;
	private final Map<Skill, Integer> wield = new LinkedHashMap<>();
	private final Map<Skill, Integer> make = new LinkedHashMap<>();

	GuideItem(String name)
	{
		this.name = name;
	}

	/** Adds one level an entry needs; the section is the guide section listing it there, or null when hidden. */
	void add(Skill skill, int level, String section)
	{
		if (level <= 1)
		{
			return;
		}
		boolean equip = COMBAT.contains(skill) || (section != null && EQUIPMENT.matcher(section).find());
		(equip ? wield : make).merge(skill, level, Math::max);
	}

	boolean isEmpty()
	{
		return wield.isEmpty() && make.isEmpty();
	}
}

