	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		MenuEntry entry = event.getMenuEntry();
		if (entry.getParam1() == InterfaceID.Questlist.LIST)
		{
			Task task = tasks.byName(questListName(entry));
			if (task != null && !hasPinEntry())
			{
				addTaskPinEntry(task);
			}
			return;
		}
		if (EXAMINE.equals(entry.getOption()) && entry.getItemId() > 0)
		{
			// an item in the inventory, bank, equipment or a shop with a goal to pin
			Task task = tasks.byItem(itemManager.canonicalize(entry.getItemId()));
			if (task != null && !hasPinEntry())
			{
				addTaskPinEntry(task);
			}
			return;
		}
		Skill skill = Skills.forStatsWidget(entry.getParam1());
		if (skill == null || hasPinEntry())
		{
			return;
		}
		addPinEntry(skill);
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		net.runelite.api.Point mouse = client.getMouseCanvasPosition();
		Skill skill = pinnedOverlay.skillAt(mouse.getX(), mouse.getY());
		if (skill != null && !hasPinEntry())
		{
			addPinEntry(skill);
		}
		String task = pinnedOverlay.taskAt(mouse.getX(), mouse.getY());
		if (task != null && !hasPinEntry())
		{
			if (tallies.containsKey(task))
			{
				addTallyEntries(task);
			}
			else
			{
				addCheckOffEntry(task);
				addTaskPinEntry(tasks.get(task));
			}
		}
		Skill guideSkill = skillGuide.skill();
		if (guideSkill == null || hasPinEntry())
		{
			return;
		}
		int item = skillGuide.itemAt(mouse.getX(), mouse.getY());
		Task goal = item <= 0 ? null : tasks.byItem(item) != null ? tasks.byItem(item) : tasks.byItem(itemManager.canonicalize(item));
		Unlock unlock = goal == null ? skillGuide.unlockAt(mouse.getX(), mouse.getY()) : null;
		if (item > 0)
		{
			int counted = itemManager.canonicalize(item);
			client.getMenu().createMenuEntry(1)
				.setOption(SET_AMOUNT)
				.setTarget(ColorUtil.wrapWithColorTag(itemManager.getItemComposition(counted).getName(), config.colorNext()))
				.setType(MenuAction.RUNELITE)
				.onClick(e -> askTally(guideSkill, counted));
		}
		if (goal != null)
		{
			addTaskPinEntry(goal);
		}
		else if (unlock != null)
		{
			// a quest or diary row pins the quest or diary itself
			addTaskPinEntry(unlock.getType() == Unlock.Type.UNLOCK ? tasks.get(TaskRepository.unlockKey(guideSkill, unlock))
				: tasks.get(unlock.getWiki()));
		}
	}

	/** Unpin, Set amount goal and Reset count for an amount goal's card, just above Cancel. */
	private void addTallyEntries(String key)
	{
		Tally tally = tallies.get(key);
		String target = ColorUtil.wrapWithColorTag(tally.getName(), config.colorNext());
		client.getMenu().createMenuEntry(1)
			.setOption("Reset count")
			.setTarget(target)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> resetTally(key));
		client.getMenu().createMenuEntry(1)
			.setOption(SET_AMOUNT)
			.setTarget(target)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> askTally(tally.getSkill(), tally.getItem()));
		client.getMenu().createMenuEntry(1)
			.setOption(UNPIN)
			.setTarget(target)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> toggleTask(key));
	}

	/**
	 * Check off, with each requirement the game doesn't count as met to tick by hand, like a quest done before this
	 * plugin could see it, and the ones ticked to untick.
	 */
	private void addCheckOffEntry(String key)
	{
		Task task = tasks.get(key);
		if (task == null)
		{
			return;
		}
		Set<String> checked = checkedFor(key);
		List<Requirement> open = requirements(task, Collections.emptySet()).stream()
			.filter(r -> !r.isMet())
			.collect(Collectors.toList());
		if (open.isEmpty())
		{
			return;
		}
		MenuEntry parent = client.getMenu().createMenuEntry(1)
			.setOption("Check off")
			.setTarget(ColorUtil.wrapWithColorTag(task.getName(), config.colorNext()))
			.setType(MenuAction.RUNELITE);
		Menu sub = parent.createSubMenu();
		// each entry goes on top, so the list is built from the bottom up
		for (int i = open.size() - 1; i >= 0; i--)
		{
			Requirement r = open.get(i);
			boolean done = checked.contains(r.getLabel());
			sub.createMenuEntry(-1)
				.setOption(done ? "Uncheck" : "Check off")
				.setTarget(ColorUtil.wrapWithColorTag(r.getLabel() + (r.getProgress().isEmpty() ? "" : " " + r.getProgress()),
					done ? Color.GREEN : Color.RED))
				.setType(MenuAction.RUNELITE)
				.onClick(e -> toggleCheckedOff(key, r.getLabel()));
		}
	}

	/** The labels of a card's requirements checked off by hand. Any thread. */
	private Set<String> checkedFor(String key)
	{
		Set<String> labels = new HashSet<>();
		String prefix = key + CHECK_SEPARATOR;
		for (String entry : checkedOff)
		{
			if (entry.startsWith(prefix))
			{
				labels.add(entry.substring(prefix.length()));
			}
		}
		return labels;
	}

	/** Ticks a card's requirement off by hand, or unticks it. Client thread. */
	private void toggleCheckedOff(String key, String label)
	{
		Set<String> entries = new TreeSet<>(checkedOff);
		String entry = key + CHECK_SEPARATOR + label;
		if (!entries.remove(entry))
		{
			entries.add(entry);
		}
		setCheckedOff(entries);
	}

	private void setCheckedOff(Set<String> entries)
	{
		checkedOff = Collections.unmodifiableSet(entries);
		taskCache.clear();
		configManager.setConfiguration(NextUnlocksConfig.GROUP, "checkedOff", String.join("\n", entries));
	}

	private boolean hasPinEntry()
	{
		for (MenuEntry entry : client.getMenu().getMenuEntries())
		{
			if (entry.getType() == MenuAction.RUNELITE && (PIN.equals(entry.getOption()) || UNPIN.equals(entry.getOption())))
			{
				return true;
			}
		}
		return false;
	}

	/** Adds Pin or Unpin and Set goal just above Cancel, so they never become the left-click action. */
	private void addPinEntry(Skill skill)
	{
		addGoalEntry(skill);
		client.getMenu().createMenuEntry(1)
			.setOption(pinned.contains(skill) ? UNPIN : PIN)
			.setTarget(ColorUtil.wrapWithColorTag(skill.getName() + " unlocks", config.colorNext()))
			.setType(MenuAction.RUNELITE)
			.onClick(e -> togglePin(skill));
	}

	/** The quest a quest list entry is for, from the list's text since the entry's target can be empty. */
	private String questListName(MenuEntry entry)
	{
		Widget list = client.getWidget(entry.getParam1());
		Widget child = list == null ? null : list.getChild(entry.getParam0());
		String text = child != null && child.getText() != null && !child.getText().isEmpty() ? child.getText() : entry.getTarget();
		return Text.removeTags(text).trim();
	}

	/** Pin or Unpin for a quest, diary or item card, just above Cancel. */
	private void addTaskPinEntry(Task task)
	{
		if (task == null)
		{
			return;
		}
		client.getMenu().createMenuEntry(1)
			.setOption(pinnedTasks.contains(task.getWiki()) ? UNPIN : PIN)
			.setTarget(ColorUtil.wrapWithColorTag(task.getName() + (task.isItem() ? " goal" : task.isUnlock() ? " unlock" : " requirements"),
				config.colorNext()))
			.setType(MenuAction.RUNELITE)
			.onClick(e -> toggleTask(task.getWiki()));
	}

	/** Pins or unpins a quest or diary card. Client thread. */
	private void toggleTask(String wiki)
	{
		if (!pinnedTasks.remove(wiki))
		{
			pinnedTasks.add(wiki);
			questsDirty = true;
		}
		else
		{
			// an unpinned card forgets its amount goal and what was checked off on it
			if (tallies.remove(wiki) != null)
			{
				saveTallies();
			}
			Set<String> entries = new TreeSet<>(checkedOff);
			if (entries.removeIf(e -> e.startsWith(wiki + CHECK_SEPARATOR)))
			{
				setCheckedOff(entries);
			}
		}
		saveTaskPins();
		pushToPanel();
	}

	/** {@link #toggleTask} from the panel's thread. */
	void toggleTaskLater(String wiki)
	{
		clientThread.invokeLater(() -> toggleTask(wiki));
	}

	/** The goals set, in the order they were. Any thread. */
	List<Goal> goals()
	{
		return goals;
	}

	/** The name of a pinned quest, diary or item goal. */
	String taskName(String wiki)
	{
		Tally tally = tallies.get(wiki);
		return tally != null ? tally.goalText() : tasks.name(wiki);
	}

	/**
	 * The card for an {@link TaskRepository#UNLOCK} key, from the unlocks as loaded now: its level, and the quest it needs
	 * by wiki title when the bundled quests know it, else by name. Null when no unlock matches. Any thread.
	 */
	private Task unlockTask(String key)
	{
		Skill skill = TaskRepository.unlockSkill(key);
		int level = TaskRepository.unlockLevel(key);
		String text = TaskRepository.unlockText(key);
		if (skill == null)
		{
			return null;
		}
		for (Unlock u : repository.all(skill))
		{
			if (u.getLevel() == level && u.getType() == Unlock.Type.UNLOCK && u.getText().equals(text))
			{
				Quest quest = u.getQuest() == null ? null : QUESTS.get(u.getQuest());
				Task questTask = quest == null ? null : tasks.byName(quest.getName());
				return TaskRepository.unlockTask(skill, u, questTask != null ? questTask.getWiki() : quest == null ? null : quest.getName());
			}
		}
		return null;
	}

	/** Asks in the chatbox for a quest, diary or item to pin, and pins the best match. Client thread. */
	void askPinTask()
	{
		chatboxPanelManager.openTextInput("Pin a quest, diary or item:")
			.onDone((String text) ->
			{
				Task task = tasks.find(text);
				if (text.trim().isEmpty())
				{
					return;
				}
				if (task == null)
				{
					sendChat("", "Nothing found for", text.trim());
				}
				else if (!pinnedTasks.contains(task.getWiki()))
				{
					toggleTask(task.getWiki());
				}
			})
			.build();
	}

	private void saveTaskPins()
	{
		pinnedTaskTitles = Collections.unmodifiableSet(new HashSet<>(pinnedTasks));
		configManager.setConfiguration(NextUnlocksConfig.GROUP, "pinnedTasks", String.join(TASK_SEPARATOR, pinnedTasks));
	}

	/** Set goal, with the next few unlocks, the next level and 99 to pick from, and the skill's goals to remove. */
	private void addGoalEntry(Skill skill)
	{
		Integer level = levels.get(skill);
		if (level == null)
		{
			return;
		}
		List<Goal> current = goals.stream().filter(g -> g.getSkill() == skill).collect(Collectors.toList());
		List<Goal> choices = goalChoices(skill);
		if (choices.isEmpty() && current.isEmpty() && level >= Experience.MAX_REAL_LEVEL)
		{
			return;
		}

		MenuEntry parent = client.getMenu().createMenuEntry(1)
			.setOption(SET_GOAL)
			.setTarget(ColorUtil.wrapWithColorTag(skill.getName(), Skills.color(skill)))
			.setType(MenuAction.RUNELITE);
		Menu sub = parent.createSubMenu();
		// each entry goes on top, so the list is built from the bottom up
		for (Goal goal : current)
		{
			boolean levelOnly = goal.equals(Goal.level(skill, goal.getLevel()));
			goalChoice(sub, REMOVE_GOAL, levelOnly ? goal.getText() : goal.getLevel() + " " + goal.getText(), goal);
		}
		if (level < Experience.MAX_REAL_LEVEL)
		{
			sub.createMenuEntry(-1)
				.setOption("Choose level...")
				.setTarget("")
				.setType(MenuAction.RUNELITE)
				.onClick(e -> askGoalLevel(skill, level));
		}
		for (int i = choices.size() - 1; i >= 0; i--)
		{
			Goal goal = choices.get(i);
			boolean levelOnly = goal.equals(Goal.level(skill, goal.getLevel()));
			goalChoice(sub, "Level " + goal.getLevel(), levelOnly ? "" : goal.getText(), goal);
		}
	}

	/**
	 * Goals to pick from for a skill, those already set left out: the next few unlocks, the next level and 99. Empty when
	 * logged out. Client thread.
	 */
	List<Goal> goalChoices(Skill skill)
	{
		Integer level = levels.get(skill);
		if (level == null)
		{
			return Collections.emptyList();
		}
		List<Goal> choices = new ArrayList<>();
		repository.upcoming(skill, level, snapshot().upcoming(skill), GOAL_CHOICES).forEach((lvl, unlocks) ->
			choices.add(Goal.of(skill, unlocks.get(0))));
		if (level < Experience.MAX_REAL_LEVEL)
		{
			choices.add(Goal.level(skill, level + 1));
		}
		if (level + 1 < Experience.MAX_REAL_LEVEL)
		{
			choices.add(Goal.level(skill, Experience.MAX_REAL_LEVEL));
		}
		choices.removeAll(goals);
		return choices;
	}

	/** The skill's real level, or null when logged out. Client thread. */
	Integer level(Skill skill)
	{
		return levels.get(skill);
	}

	/** Asks in the chatbox for a level to aim for, above the current one. Client thread. */
	void askGoalLevel(Skill skill, int level)
	{
		chatboxPanelManager.openTextInput(skill.getName() + " goal level (" + (level + 1) + "-" + Experience.MAX_REAL_LEVEL + "):")
			.charValidator(Character::isDigit)
			.onDone((String text) ->
			{
				int target;
				try
				{
					target = Integer.parseInt(text.trim());
				}
				catch (NumberFormatException e)
				{
					return;
				}
				Goal goal = Goal.level(skill, target);
				if (target > level && target <= Experience.MAX_REAL_LEVEL && !goals.contains(goal))
				{
					toggleGoal(goal);
				}
			})
			.build();
	}

	private void goalChoice(Menu menu, String option, String text, Goal goal)
	{
		menu.createMenuEntry(-1)
			.setOption(option)
			.setTarget(ColorUtil.wrapWithColorTag(text, config.colorNext()))
			.setType(MenuAction.RUNELITE)
			.onClick(e -> toggleGoal(goal));
	}

	/** The skill's goal with the lowest level, or null. */
	private Goal nearestGoal(Skill skill)
	{
		return goals.stream()
			.filter(g -> g.getSkill() == skill)
			.min(Comparator.comparingInt(Goal::getLevel))
			.orElse(null);
	}

	/** Pins or unpins a skill's card. Client thread. */
	void togglePin(Skill skill)
	{
		if (!pinned.remove(skill))
		{
			pinned.add(skill);
		}
		configManager.setConfiguration(NextUnlocksConfig.GROUP, "pinnedSkills",
			pinned.stream().map(Skill::name).collect(Collectors.joining(",")));
	}

	private void loadPins()
	{
		pinned.clear();
		for (String name : config.pinnedSkills().split(","))
		{
			try
			{
				pinned.add(Skill.valueOf(name.trim()));
			}
			catch (IllegalArgumentException ignored)
			{
				// empty or a skill that no longer exists
			}
		}
		Set<String> checked = new TreeSet<>();
		for (String line : config.checkedOff().split("\n"))
		{
			if (!line.trim().isEmpty())
			{
				checked.add(line.trim());
			}
		}
		checkedOff = Collections.unmodifiableSet(checked);
		tallies.clear();
		for (Tally tally : Tally.parse(config.tallies()))
		{
			tallies.put(tally.key(), tally);
		}
		pinnedTasks.clear();
		for (String title : config.pinnedTasks().split(TASK_SEPARATOR))
		{
			// a skill guide item's goal only exists once the cache is read, after the pins load, and an unlock's may
			// only match once the guide's unlocks replace the wiki's
			String key = title.trim();
			if (tasks.get(key) != null || key.startsWith(TaskRepository.GUIDE_ITEM) || key.startsWith(TaskRepository.UNLOCK)
				|| tallies.containsKey(key))
			{
				pinnedTasks.add(key);
			}
		}
		// an amount goal is always pinned
		pinnedTasks.addAll(tallies.keySet());
		pinnedTaskTitles = Collections.unmodifiableSet(new HashSet<>(pinnedTasks));
	}

	private void announce(Skill skill, int from, int to)
	{
		Predicate<Unlock> filter = snapshot().shown(skill);
		for (int level = from + 1; level <= to; level++)
		{
			List<Unlock> unlocks = repository.at(skill, level, filter);
			if (unlocks.isEmpty())
			{
				continue;
			}
			String list = unlocks.stream()
				.limit(MESSAGE_ENTRIES)
				.map(Unlock::getText)
				.collect(Collectors.joining("; "));
			if (unlocks.size() > MESSAGE_ENTRIES)
			{
				list += " (+" + (unlocks.size() - MESSAGE_ENTRIES) + " more)";
			}
			sendChat("New at ", skill.getName() + " " + level + ":", list);
		}
	}

	/** A game message: a plain prefix, then the skill and level and the unlocks in their colors. */
	private void sendChat(String prefix, String label, String text)
	{
		String colored = new ChatMessageBuilder()
			.append(config.colorChatLevel(), label)
			.append(" ")
			.append(config.colorChatUnlocks(), text)
			.build();
		// chat fonts have no bold; a black shadow makes the text heavier and keeps yellow readable on parchment.
		// The builder escapes tags in appended text, so the shadow goes around what it built.
		if (config.chatShadow())
		{
			colored = "<shad=000000>" + colored + "</shad>";
		}
		String message = new ChatMessageBuilder()
			.append(ChatColorType.NORMAL)
			.append(prefix)
			.build() + colored;
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	/** Switches to the game's skill guide unlocks once the cache is loaded. Client thread. */
	private void loadSkillGuide()
	{
		if (repository.isSkillGuide() || client.getGameState().getState() < GameState.LOGIN_SCREEN.getState())
		{
			return;
		}
		try
		{
			repository.loadSkillGuide(client);
			tasks.addGuide(repository.getGuideItems());
			// unlock pins match the guide's unlocks now
			tasks.setUnlocks(this::unlockTask);
		}
		catch (RuntimeException e)
		{
			log.warn("Couldn't read the skill guide; using the bundled wiki unlocks", e);
		}
		clearTooltips();
		panelDirty = true;
	}

	/** Checks which required quests are unfinished. Client thread, logged in. */
	private void refreshQuests()
	{
		questsDirty = false;
		ticksSinceQuestRefresh = 0;
		Set<Integer> toDo = new HashSet<>();
		for (int id : repository.requiredQuests())
		{
			Quest quest = QUESTS.get(id);
			// quests newer than this RuneLite's list can't be checked; they're left as usable
			if (quest != null && quest.getState(client) != QuestState.FINISHED)
			{
				toDo.add(id);
			}
		}
		Set<String> finished = new HashSet<>();
		if (config.almostThere())
		{
			Set<String> titles = repository.questTitles();
			for (Quest quest : Quest.values())
			{
				if (titles.contains(quest.getName()) && quest.getState(client) == QuestState.FINISHED)
				{
					finished.add(quest.getName());
				}
			}
		}
		refreshTaskQuests();
		Set<Integer> unfinished = config.greyOutLocked() ? toDo : Collections.emptySet();
		if (!unfinished.equals(unfinishedQuests))
		{
			unfinishedQuests = unfinished;
			clearTooltips();
			panelDirty = true;
		}
		if (!toDo.equals(questsToDo) || !finished.equals(finishedQuests))
		{
			questsToDo = toDo;
			finishedQuests = finished;
			panelDirty = true;
		}
	}

	/** Checks the pinned quests and the quests they need, and unpins quests once they're done. Client thread. */
	private void refreshTaskQuests()
	{
		Map<String, QuestState> states = new HashMap<>();
		for (String title : pinnedTasks)
		{
			Task task = tasks.get(title);
			if (task == null)
			{
				continue;
			}
			questState(task.getWiki(), states);
			for (String quest : task.getQuests())
			{
				questState(quest, states);
				// and the quests that quest needs, for the lines under it
				Task needed = tasks.get(quest);
				if (needed != null)
				{
					needed.getQuests().forEach(q -> questState(q, states));
				}
			}
		}
		if (states.equals(questStates))
		{
			return;
		}
		Map<String, QuestState> before = questStates;
		questStates = states;
		taskCache.clear();
		boolean unpinned = false;
		for (Iterator<String> it = pinnedTasks.iterator(); it.hasNext(); )
		{
			String title = it.next();
			QuestState was = before.get(title);
			// only as it happens, so a finished quest can still be pinned
			if (was != null && was != QuestState.FINISHED && states.get(title) == QuestState.FINISHED)
			{
				it.remove();
				unpinned = true;
				sendChat("Quest complete! ", tasks.name(title), "is unpinned.");
			}
		}
		if (unpinned)
		{
			saveTaskPins();
			pushToPanel();
		}
	}

	/** Adds the state of the quest with this wiki title, when this RuneLite knows the quest. */
	private void questState(String wiki, Map<String, QuestState> states)
	{
		Quest quest = QUESTS_BY_NAME.get(tasks.name(wiki));
		if (quest != null)
		{
			states.put(wiki, quest.getState(client));
		}
	}

	/** A requirement's color, faded halfway to the card's "+N more" gray, for the material line under it. */
	private static Color materialShade(Color color, CardTheme theme)
	{
		Color gray = theme.getMore();
		return new Color((color.getRed() + gray.getRed()) / 2, (color.getGreen() + gray.getGreen()) / 2,
			(color.getBlue() + gray.getBlue()) / 2, color.getAlpha());
	}

	/** Card for a pinned quest, diary or item: its hard requirements, unmet first. Client thread. */
	LayoutableRenderableEntity taskCard(String wiki)
	{
		if (levels.isEmpty())
		{
			return null;
		}
		Tally tally = tallies.get(wiki);
		Task task = tally == null ? tasks.get(wiki) : null;
		if (task == null && tally == null)
		{
			return null;
		}
		TooltipBox cached = taskCache.get(wiki);
		if (cached != null)
		{
			return cached;
		}
		Snapshot snapshot = snapshot();
		Palette palette = snapshot.getPalette();
		CardTheme theme = theme(palette, true);
		int textSize = config.tooltipTextSize();
		Font regular = FontManager.getRunescapeFont();
		Font font = theme.font(textSize);
		Font small = theme.font(Math.max(MATERIAL_MIN_SIZE, Math.round(textSize * MATERIAL_SIZE)));

		if (tally != null)
		{
			return tallyCard(wiki, tally, theme, font, small, textSize, regular);
		}
		List<Requirement> requirements = requirements(task, checkedFor(wiki));
		long met = requirements.stream().filter(Requirement::isMet).count();

		PanelComponent card = new PanelComponent();
		List<LayoutableRenderableEntity> lines = card.getChildren();
		QuestState state = questStates.get(wiki);
		boolean goal = task.isItem() || task.isUnlock();
		String status = goal ? (met == requirements.size() ? "Ready" : task.isItem() ? "Item goal" : "Unlock") : task.isDiary() ? "Diary" : state == QuestState.FINISHED ? "Completed"
			: state == QuestState.IN_PROGRESS ? "In progress" : state == QuestState.NOT_STARTED ? "Not started" : "";
		Color statusColor = goal ? (met == requirements.size() ? theme.getMet() : theme.getXpValue())
			: state == QuestState.FINISHED ? theme.getMet() : state == QuestState.IN_PROGRESS ? Color.YELLOW
			: state == QuestState.NOT_STARTED ? theme.getUnmet() : theme.getXpValue();
		// the item's picture, drawn as it loads, or the quest or diary tab icon, which can be missing before the cache is
		// ready; don't keep a card without it
		BufferedImage icon = task.getItem() > 0 ? itemManager.getImage(task.getItem())
			: task.isUnlock() ? (task.getSprite() > 0 ? spriteManager.getSprite(task.getSprite(), 0)
				: skillIconManager.getSkillImage(task.getSkills().keySet().iterator().next(), true))
			: spriteManager.getSprite(task.isDiary() ? SpriteID.SideIcons.ACHIEVEMENT_DIARIES : SpriteID.SideIcons.QUEST, 0);
		lines.add(new CardHeader(icon, task.getName(), theme.getTaskTitle(), theme.titleFont(textSize, TASK_TITLE_GROWTH),
			(double) textSize / regular.getSize(), theme));
		lines.add(new CardLine(theme, font)
			.left(status, statusColor)
			.right(requirements.isEmpty() ? "No requirements" : met + "/" + requirements.size() + " met",
				met == requirements.size() ? theme.getMet() : theme.getXpValue()));
		for (Requirement r : requirements.subList(0, Math.min(TASK_LINES, requirements.size())))
		{
			Color color = r.isMet() ? theme.getMet() : theme.getUnmet();
			lines.add(new CardLine(theme, font).left(r.getLabel(), color).right(r.getProgress(), color));
			if (r.getMaterial() != null)
			{
				lines.add(new CardMaterial(theme, small, r.getMaterialItem() > 0 ? itemManager.getImage(r.getMaterialItem()) : null,
					r.getMaterial(), materialShade(color, theme)));
			}
			if (!r.isMet() && r.getQuest() != null)
			{
				addQuestSubLines(lines, r, theme, small);
			}
		}
		if (requirements.size() > TASK_LINES)
		{
			lines.add(new CardLine(theme, font).left("+" + (requirements.size() - TASK_LINES) + " more", theme.getMore()));
		}
		card.setPreferredSize(new Dimension((int) (ComponentConstants.STANDARD_WIDTH * textSize / regular.getSize() * theme.widthScale(textSize))
			+ 2 * (theme.getPadding() - PANEL_PADDING), 0));

		TooltipBox box = new TooltipBox(card, theme, Collections.emptyList());
		if (icon != null)
		{
			taskCache.put(wiki, box);
		}
		return box;
	}

	/** The task's requirements as the player stands, with the ones checked off by hand counted as met. Client thread. */
	private List<Requirement> requirements(Task task, Set<String> checked)
	{
		Player player = client.getLocalPlayer();
		int combat = player == null ? 0 : player.getCombatLevel();
		return Requirement.checkOff(Requirement.check(task, snapshot()::effectiveLevel,
			client.getVarpValue(VarPlayerID.QP), combat, q -> questStates.get(q) == QuestState.FINISHED, tasks::name,
			config.itemMakingLevels() || !task.isItem()), checked);
	}

	/**
	 * Under an unfinished quest the card needs, what that quest still needs in tiny text: its skill levels with the
	 * skill's icon and its quests with the quest icon, at most {@link #QUEST_SUB_LINES} then "+N more".
	 */
	private void addQuestSubLines(List<LayoutableRenderableEntity> lines, Requirement quest, CardTheme theme, Font small)
	{
		Task task = tasks.get(quest.getQuest());
		if (task == null)
		{
			task = tasks.byName(quest.getLabel());
		}
		if (task == null)
		{
			return;
		}
		List<Requirement> open = requirements(task, checkedFor(task.getWiki())).stream()
			.filter(r -> !r.isMet())
			.collect(Collectors.toList());
		Color shade = materialShade(theme.getUnmet(), theme);
		for (Requirement r : open.subList(0, Math.min(QUEST_SUB_LINES, open.size())))
		{
			BufferedImage icon = r.getSkill() != null ? skillIconManager.getSkillImage(r.getSkill(), true)
				: r.getQuest() != null ? spriteManager.getSprite(SpriteID.SideIcons.QUEST, 0) : null;
			lines.add(new CardMaterial(theme, small, icon, r.getLabel() + (r.getProgress().isEmpty() ? "" : " " + r.getProgress()), shade));
		}
		if (open.size() > QUEST_SUB_LINES)
		{
			lines.add(new CardMaterial(theme, small, null, "+" + (open.size() - QUEST_SUB_LINES) + " more", theme.getMore()));
		}
	}

	/** Card for an amount goal: the item, what's done of the target, a bar in the skill's color and the skill. */
	private LayoutableRenderableEntity tallyCard(String key, Tally tally, CardTheme theme, Font font, Font small, int textSize,
		Font regular)
	{
		PanelComponent card = new PanelComponent();
		List<LayoutableRenderableEntity> lines = card.getChildren();
		BufferedImage icon = itemManager.getImage(tally.getItem());
		lines.add(new CardHeader(icon, tally.getName(), theme.getTaskTitle(), theme.titleFont(textSize, TASK_TITLE_GROWTH),
			(double) textSize / regular.getSize(), theme));
		Color color = tally.isDone() ? theme.getMet() : theme.getXpValue();
		lines.add(new CardLine(theme, font)
			.left(tally.isDone() ? "Done!" : Tally.verb(tally.getSkill()) + " " + String.format(Locale.ROOT, "%,d", tally.getTarget()), color)
			.right(String.format(Locale.ROOT, "%,d/%,d", tally.getCount(), tally.getTarget()), color));
		lines.add(new PinBar(theme, 0, tally.getTarget(), Math.min(tally.getCount(), tally.getTarget()), Skills.color(tally.getSkill()), null));
		lines.add(new CardMaterial(theme, small, skillIconManager.getSkillImage(tally.getSkill(), true), tally.getSkill().getName(),
			materialShade(theme.getXpValue(), theme)));
		card.setPreferredSize(new Dimension((int) (ComponentConstants.STANDARD_WIDTH * textSize / regular.getSize() * theme.widthScale(textSize))
			+ 2 * (theme.getPadding() - PANEL_PADDING), 0));
		TooltipBox box = new TooltipBox(card, theme, Collections.emptyList());
		if (icon != null)
		{
			taskCache.put(key, box);
		}
		return box;
	}

	private void loadHiddenSections()
	{
		Set<String> sections = new HashSet<>();
		for (String key : config.hiddenSections().split(SECTION_SEPARATOR))
		{
			if (!key.trim().isEmpty())
			{
				sections.add(key.trim());
			}
		}
		hiddenSections = Collections.unmodifiableSet(sections);
	}

	/** Hides or shows a skill guide section; the config change refreshes the panel. Any thread. */
	private void setSectionHidden(String key, boolean hide)
	{
		Set<String> sections = new TreeSet<>(hiddenSections);
		if (hide ? sections.add(key) : sections.remove(key))
		{
			configManager.setConfiguration(NextUnlocksConfig.GROUP, "hiddenSections", String.join(SECTION_SEPARATOR, sections));
		}
	}

	/** Sets a goal, or drops it when it is one. Any thread. */
	synchronized void toggleGoal(Goal goal)
	{
		List<Goal> updated = new ArrayList<>(goals);
		if (!updated.remove(goal))
		{
			updated.add(goal);
		}
		saveGoals(updated);
	}

	/** The config change puts up the infoboxes and refreshes the panel. */
	private synchronized void saveGoals(List<Goal> updated)
	{
		goals = Collections.unmodifiableList(updated);
		configManager.setConfiguration(NextUnlocksConfig.GROUP, "goals", Goal.format(updated));
	}

	/** Announces and drops the skill's goals the level reaches. Client thread. */
	private void reachGoals(Skill skill, int level)
	{
		List<Goal> reached = goals.stream()
			.filter(g -> g.getSkill() == skill && g.getLevel() <= level)
			.collect(Collectors.toList());
		if (reached.isEmpty())
		{
			return;
		}
		for (Goal goal : reached)
		{
			String label = goal.getSkill().getName() + " " + goal.getLevel() + ":";
			sendChat("Goal reached! ", label, goal.getText());
			notifier.notify(config.goalNotification(), "Goal reached! " + label + " " + goal.getText());
		}
		synchronized (this)
		{
			List<Goal> remaining = new ArrayList<>(goals);
			remaining.removeAll(reached);
			saveGoals(remaining);
		}
	}

	/** Puts up an infobox per goal, or none when they're off. Client thread. */
	private void syncGoalBoxes()
	{
		goalBoxes.forEach(infoBoxManager::removeInfoBox);
		goalBoxes.clear();
		if (!config.goalInfoboxes())
		{
			return;
		}
		for (Goal goal : goals)
		{
			BufferedImage icon = goalImage(goal);
			GoalInfoBox box = new GoalInfoBox(GoalInfoBox.withTextRoom(icon), this, goal, client::getSkillExperience, config.colorNext());
			if (icon instanceof AsyncBufferedImage)
			{
				// item pictures load later; redraw the box's picture once this one has
				((AsyncBufferedImage) icon).onLoaded(() ->
				{
					box.setImage(GoalInfoBox.withTextRoom(icon));
					infoBoxManager.updateInfoBoxImage(box);
				});
			}
			box.getMenuEntries().add(new OverlayMenuEntry(MenuAction.RUNELITE_INFOBOX, REMOVE_GOAL,
				ColorUtil.wrapWithColorTag(goal.getText(), config.colorNext())));
			goalBoxes.add(box);
			infoBoxManager.addInfoBox(box);
		}
	}

	/** The goal's item or spell picture, or its skill's icon. Client thread. */
	BufferedImage goalImage(Goal goal)
	{
		Unlock u = repository.all(goal.getSkill()).stream()
			.filter(x -> goal.is(goal.getSkill(), x))
			.findFirst()
			.orElse(null);
		BufferedImage image = null;
		if (u != null && u.getItem() != null)
		{
			image = itemManager.getImage(u.getItem());
		}
		else if (u != null && u.getSprite() != null)
		{
			image = spriteManager.getSprite(u.getSprite(), 0);
		}
		return image != null ? image : skillIconManager.getSkillImage(goal.getSkill(), false);
	}

	@Subscribe
	public void onInfoBoxMenuClicked(InfoBoxMenuClicked event)
	{
		if (!REMOVE_GOAL.equals(event.getEntry().getOption()) || !(event.getInfoBox() instanceof GoalInfoBox)
			|| !goalBoxes.contains(event.getInfoBox()))
		{
			return;
		}
		synchronized (this)
		{
			List<Goal> remaining = new ArrayList<>(goals);
			remaining.remove(((GoalInfoBox) event.getInfoBox()).getGoal());
			saveGoals(remaining);
		}
	}

	/** Current stats and settings. Client thread. */
	private Snapshot snapshot()
	{
		Map<Skill, Integer> levelCopy = new EnumMap<>(Skill.class);
		Map<Skill, Integer> xpCopy = new EnumMap<>(Skill.class);
		Map<Skill, Integer> boosted = new EnumMap<>(Skill.class);
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			levelCopy.putAll(levels);
			for (Skill skill : levels.keySet())
			{
				xpCopy.put(skill, client.getSkillExperience(skill));
				int boost = client.getBoostedSkillLevel(skill);
				if (config.countBoosts() && boost > levels.get(skill))
				{
					boosted.put(skill, boost);
				}
			}
		}
		return new Snapshot(levelCopy, xpCopy, boosted, filter(), config.levelsAhead(), unfinishedQuests, hiddenSections, Palette.of(config),
			questsToDo, finishedQuests, goals, config.almostThere(), pinnedTaskTitles);
	}

	/** Copies current stats for the panel. Client thread. */
	private void pushToPanel()
	{
		panelDirty = false;
		ticksSincePanelRefresh = 0;
		NextUnlocksPanel target = panel;
		if (target == null)
		{
			return;
		}
		Snapshot snapshot = snapshot();
		SwingUtilities.invokeLater(() -> target.update(snapshot));
	}
}

package com.nextunlocks;

import java.awt.Color;
import lombok.Value;

/** The configurable colors, shared by the tooltip, the panel and the skill guide. */
@Value
class Palette
{
	static final Palette DEFAULT = new Palette(new Color(0xff9040), new Color(0xff9040), new Color(0xc86a28),
		new Color(0x4d4d4d), Color.YELLOW, new Color(0x4cd94c), new Color(0x8a8a8a));

	/** The next unlock: the tooltip's level line, the skill guide's next level. */
	Color next;
	/** The skill guide's next-unlock rows, and the tooltip when outlined. */
	Color outline;
	Color progress;
	Color progressBackground;
	/** Level numbers on unlock icons. */
	Color level;
	/** Unlocks reached with a boost. */
	Color boost;
	/** Quest-locked unlocks. */
	Color locked;

	static Palette of(NextUnlocksConfig config)
	{
		return new Palette(config.colorNext(), config.colorOutline(), config.colorProgress(), config.colorProgressBackground(),
			config.colorLevel(), config.colorBoost(), config.colorLocked());
	}

	/** The color as a widget's RGB, ignoring alpha. */
	static int rgb(Color color)
	{
		return color.getRGB() & 0xffffff;
	}

	/** The color's alpha as a widget's opacity, where 0 is opaque. */
	static int opacity(Color color)
	{
		return 255 - color.getAlpha();
	}
}

package com.nextunlocks;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Paint;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.RoundRectangle2D;
import java.text.DecimalFormat;
import java.util.Random;
import java.util.function.Supplier;
import lombok.Setter;
import lombok.Value;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/**
 * The progress bar on cards, in one of a few styles. The arcade one sits still while the unlock is far off, starts to
 * twitch past halfway, and splits into shifting color layers that shake harder as it closes in. With the level-up
 * effect on, a reached unlock holds the bar at a flashing 100%, then it bursts into colored pixels; other level-ups
 * just burst.
 */
class PinBar implements LayoutableRenderableEntity
{
	static final int HEIGHT = 16;
	/** How long a reached unlock shows the full rainbow bar before it bursts. */
	static final long FULL_MS = 1400;
	static final long BURST_MS = 1100;
	/** The jitter moves in steps rather than smoothly, like an old arcade cabinet. */
	private static final long STEP_MS = 45;
	private static final int SEGMENT = 6;
	/** Width of a segmented bar's blocks. */
	private static final int BLOCK = 5;
	/** The classic bar's label, as RuneLite's own progress bar writes it. */
	private static final DecimalFormat PERCENT = new DecimalFormat("0.0");
	private static final float GRAVITY = 300;
	private static final Color[] PIXELS = {
		new Color(255, 64, 64), new Color(255, 160, 32), new Color(255, 236, 64), new Color(96, 255, 96),
		new Color(64, 232, 255), new Color(96, 128, 255), new Color(232, 96, 255), Color.WHITE,
	};

	/** A level-up to show: when it happened, and whether it reached the unlock the bar was filling toward. */
	@Value
	static class LevelUp
	{
		long at;
		boolean unlock;
	}

	private final NextUnlocksConfig.BarStyle style;
	private final double minimum;
	private final double maximum;
	@Setter
	private double value;
	private final Color color;
	private final Color background;
	private final Color textColor;
	private final Color[] pixels;
	/** The skill's latest level-up, or null; null when the effect is off. */
	private final Supplier<LevelUp> levelUp;

	private Point location = new Point();
	private Dimension preferred = new Dimension();
	/** Where the bar was last laid out, unshaken; bursts fly out from here. */
	private Rectangle bounds = new Rectangle();

	/** A bar in a theme's style and colors; the level-up goes unused when the theme has the effect off. */
	PinBar(CardTheme theme, double minimum, double maximum, double value, Color color, Supplier<LevelUp> levelUp)
	{
		this(theme.getBar(), minimum, maximum, value, color, theme.getBarBackground(), theme.getBarText(), theme.getBurst(),
			theme.isLevelUp() ? levelUp : null);
	}

	PinBar(NextUnlocksConfig.BarStyle style, double minimum, double maximum, double value, Color color, Color background,
		Color textColor, Color[] pixels, Supplier<LevelUp> levelUp)
	{
		this.style = style;
		this.textColor = textColor;
		this.pixels = pixels == null ? PIXELS : pixels;
		this.minimum = minimum;
		this.maximum = maximum;
		this.value = value;
		this.color = color;
		this.background = background;
		this.levelUp = levelUp;
	}

	/** 0 to 1. */
	double progress()
	{
		return maximum <= minimum ? 1 : Math.max(0, Math.min(1, (value - minimum) / (maximum - minimum)));
	}

	/** How wild the bar gets: nothing up to halfway, rising faster and faster to 1 at 100%. */
	static double heat(double progress)
	{
		if (progress <= 0.5)
		{
			return 0;
		}
		double t = Math.min(1, (progress - 0.5) / 0.5);
		return t * t;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		int width = preferred.width;
		bounds = new Rectangle(location.x, location.y, width, HEIGHT);
		if (width <= 2)
		{
			return new Dimension(width, HEIGHT);
		}

		long now = System.currentTimeMillis();
		LevelUp up = levelUp == null ? null : levelUp.get();
		boolean full = up != null && up.isUnlock() && now - up.getAt() < FULL_MS;
		double progress = full ? 1 : progress();

		Object antialias = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		Object textAntialias = graphics.getRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
		Color oldColor = graphics.getColor();
		Paint oldPaint = graphics.getPaint();
		switch (style)
		{
			case ARCADE:
				renderArcade(graphics, width, now, full, progress);
				break;
			case SEGMENTED:
				renderSegmented(graphics, width, now, full, progress);
				break;
			case MODERN:
				renderModern(graphics, width, now, full, progress);
				break;
			default:
				renderClassic(graphics, width, now, full, progress);
				break;
		}
		graphics.setPaint(oldPaint);
		graphics.setColor(oldColor);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, antialias);
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, textAntialias);
		return new Dimension(width, HEIGHT);
	}

	/** Like RuneLite's own bar; a reached unlock flashes it. */
	private void renderClassic(Graphics2D graphics, int width, long now, boolean full, double progress)
	{
		int x = location.x;
		int y = location.y;
		graphics.setColor(background);
		graphics.fillRect(x, y, width, HEIGHT);
		graphics.setColor(full ? mix(color, Color.WHITE, pulse(now, 300) * 0.6) : color);
		graphics.fillRect(x, y, (int) (width * progress), HEIGHT);
		String text = PERCENT.format(progress * 100) + "%";
		FontMetrics metrics = graphics.getFontMetrics();
		label(graphics, text, x + (width - metrics.stringWidth(text)) / 2,
			y + (HEIGHT - metrics.getHeight()) / 2 + metrics.getHeight(), textColor);
	}

	/** Blocks that light up one by one; the last one blinks near the end, and they chase in color at 100%. */
	private void renderSegmented(Graphics2D graphics, int width, long now, boolean full, double progress)
	{
		int x = location.x;
		int y = location.y;
		long step = now / STEP_MS;
		graphics.setColor(Color.BLACK);
		graphics.fillRect(x, y, width, HEIGHT);
		graphics.setColor(background);
		graphics.fillRect(x + 1, y + 1, width - 2, HEIGHT - 2);
		int inner = width - 4;
		int blocks = Math.max(1, (inner + 1) / (BLOCK + 1));
		int start = x + 2 + (inner - (blocks * (BLOCK + 1) - 1)) / 2;
		int lit = (int) Math.round(progress * blocks);
		for (int i = 0; i < lit; i++)
		{
			Color c = color;
			if (full)
			{
				c = pixels == PIXELS
					? Color.getHSBColor((float) (i / (double) blocks - (now % 900) / 900.0), 0.8f, 1f)
					: pixels[(int) ((i + step / 2) % pixels.length)];
			}
			else if (i == lit - 1 && progress > 0.75 && (step / 4) % 2 == 0)
			{
				c = mix(color, Color.WHITE, 0.6);
			}
			int bx = start + i * (BLOCK + 1);
			graphics.setColor(c);
			graphics.fillRect(bx, y + 2, BLOCK, HEIGHT - 4);
			graphics.setColor(mix(c, Color.WHITE, 0.35));
			graphics.fillRect(bx, y + 2, BLOCK, 1);
		}
		centered(graphics, width, progress, full ? pixels[(int) (step % pixels.length)] : textColor);
	}

	/** A smooth rounded bar with a gradient; a reached unlock makes it pulse. */
	private void renderModern(Graphics2D graphics, int width, long now, boolean full, double progress)
	{
		int x = location.x;
		int y = location.y;
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int height = HEIGHT - 2;
		Shape track = new RoundRectangle2D.Double(x, y + 1, width, height, height, height);
		graphics.setColor(background);
		graphics.fill(track);
		int fill = (int) Math.round(width * progress);
		if (fill > 0)
		{
			Color c = full ? mix(color, Color.WHITE, pulse(now, 420) * 0.5) : color;
			graphics.setPaint(new GradientPaint(x, 0, mix(c, Color.BLACK, 0.15), x + Math.max(1, fill), 0, mix(c, Color.WHITE, 0.3)));
			graphics.fill(new RoundRectangle2D.Double(x, y + 1, Math.max(fill, height), height, height, height));
			graphics.setPaint(new Color(255, 255, 255, 46));
			graphics.fill(new RoundRectangle2D.Double(x + 2, y + 2, Math.max(fill, height) - 4, height / 2.0 - 1, height / 2.0, height / 2.0));
		}
		if (full)
		{
			graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), (int) (90 + 140 * pulse(now, 420))));
			graphics.draw(new RoundRectangle2D.Double(x - 1, y, width + 1, height + 1, height + 2, height + 2));
		}
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		centered(graphics, width, progress, textColor);
	}

	/** The arcade cabinet bar: still to halfway, then shaking and splitting into colors more and more. */
	private void renderArcade(Graphics2D graphics, int width, long now, boolean full, double progress)
	{
		double heat = full ? 1 : heat(progress);
		long step = now / STEP_MS;

		// the shake: whole pixels, a new spot each step
		double amplitude = full ? 3.2 : heat > 0.02 ? 0.6 + heat * 1.8 : 0;
		int x = location.x + (int) Math.round(amplitude * noise(step, 1));
		int y = location.y + (int) Math.round(amplitude * 0.7 * noise(step, 2));
		int fill = (int) Math.round((width - 2) * progress);

		if (heat > 0 && fill > 0)
		{
			// color split: magenta and cyan copies pulled apart from the bar, wider as it heats up
			int alpha = (int) (60 + 140 * heat);
			int split = Math.max(1, (int) Math.round((full ? 2.5 : heat * 2) + noise(step, 3)));
			graphics.setColor(new Color(255, 0, 170, alpha));
			graphics.fillRect(x - split, y - (int) Math.round(heat * noise(step, 4)), fill + 2, HEIGHT);
			graphics.setColor(new Color(0, 230, 255, alpha));
			graphics.fillRect(x + split, y + (int) Math.round(heat * noise(step, 5)), fill + 2, HEIGHT);
		}

		// frame and empty part
		graphics.setColor(Color.BLACK);
		graphics.fillRect(x, y, width, HEIGHT);
		graphics.setColor(background);
		graphics.fillRect(x + 1, y + 1, width - 2, HEIGHT - 2);

		// filled part, one column at a time so it can run rainbow
		float[] hsb = Color.RGBtoHSB(color.getRed(), color.getGreen(), color.getBlue(), null);
		double wobble = heat * 0.12 * Math.sin(now / (420.0 - 260 * heat));
		int inner = HEIGHT - 2;
		int band = Math.max(1, inner / 3);
		for (int col = 0; col < fill; col += 2)
		{
			int w = Math.min(2, fill - col);
			Color c;
			if (full)
			{
				c = Color.getHSBColor((float) (col / (double) width - (now % 1040) / 1040.0), 0.85f, 1f);
			}
			else if (heat > 0)
			{
				// the hue runs along the bar and drifts, more as it heats up
				float hue = (float) (hsb[0] + wobble + heat * 0.18 * Math.sin(col / 9.0 - now / 160.0));
				float bright = (float) Math.min(1, hsb[2] + heat * 0.25 * (0.5 + 0.5 * Math.sin(now / 90.0 + col / 5.0)));
				c = Color.getHSBColor(hue, Math.max(hsb[1], 0.55f + 0.3f * (float) heat), bright);
			}
			else
			{
				c = color;
			}
			int cx = x + 1 + col;
			graphics.setColor(c);
			graphics.fillRect(cx, y + 1, w, inner);
			// a lit top and a shaded bottom, for the raised look of an arcade bar
			graphics.setColor(mix(c, Color.WHITE, 0.4));
			graphics.fillRect(cx, y + 1, w, band);
			graphics.setColor(mix(c, Color.BLACK, 0.4));
			graphics.fillRect(cx, y + HEIGHT - 3, w, 2);
		}

		if (fill > 0)
		{
			// segment notches
			graphics.setColor(new Color(0, 0, 0, 70));
			for (int col = SEGMENT; col < fill; col += SEGMENT)
			{
				graphics.fillRect(x + 1 + col, y + 1, 1, inner);
			}
			// a shine that sweeps across, faster as it heats up
			double period = 2200 - 1500 * heat;
			int shine = (int) ((now % (long) period) / period * (fill + 24)) - 12;
			graphics.setColor(new Color(255, 255, 255, (int) (50 + 110 * heat)));
			for (int row = 0; row < inner; row++)
			{
				int sx = shine + row / 2;
				int from = Math.max(0, sx);
				int to = Math.min(fill, sx + 4);
				if (to > from)
				{
					graphics.fillRect(x + 1 + from, y + 1 + row, to - from, 1);
				}
			}
		}

		// soft scanlines over everything
		graphics.setColor(new Color(0, 0, 0, 34));
		for (int row = 2; row < HEIGHT - 1; row += 2)
		{
			graphics.fillRect(x + 1, y + row, width - 2, 1);
		}

		if (heat > 0.15)
		{
			// a glowing outline that cycles through colors
			long cycle = full ? 960 : 2800;
			float hue = (float) ((now % cycle) / (double) cycle);
			Color glow = Color.getHSBColor(hue, 0.9f, 1f);
			graphics.setColor(new Color(glow.getRed(), glow.getGreen(), glow.getBlue(), (int) (220 * heat)));
			graphics.drawRect(x - 1, y - 1, width + 1, HEIGHT + 1);
		}

		// the percentage, flickering as it heats up
		String text = (int) Math.floor(progress * 100) + "%";
		FontMetrics metrics = graphics.getFontMetrics();
		int tx = x + (width - metrics.stringWidth(text)) / 2;
		int ty = y + (HEIGHT - metrics.getHeight()) / 2 + metrics.getAscent();
		if (full)
		{
			tx += (int) Math.round(noise(step, 6));
			ty += (int) Math.round(noise(step, 7));
		}
		Color c = textColor;
		if (full)
		{
			c = pixels[(int) (step % pixels.length)];
		}
		else if (heat > 0.5 && noise(step, 8) > 1.4 - heat)
		{
			c = new Color(255, 236, 64);
		}
		label(graphics, text, tx, ty, c);
	}

	/** The whole percentage in the middle of the bar. */
	private void centered(Graphics2D graphics, int width, double progress, Color c)
	{
		String text = (int) Math.floor(progress * 100) + "%";
		FontMetrics metrics = graphics.getFontMetrics();
		label(graphics, text, location.x + (width - metrics.stringWidth(text)) / 2,
			location.y + (HEIGHT - metrics.getHeight()) / 2 + metrics.getAscent(), c);
	}

	/** Text with a dark shadow, so it reads on any fill. */
	private static void label(Graphics2D graphics, String text, int x, int y, Color c)
	{
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + 1, y + 1);
		graphics.setColor(c);
		graphics.drawString(text, x, y);
	}

	/** 0 to 1 and back, over a period. */
	private static double pulse(long now, long period)
	{
		return 0.5 + 0.5 * Math.sin((now % period) / (double) period * Math.PI * 2);
	}

	/**
	 * The burst of pixels after a level-up, if one is going. Drawn after every card so the pixels fly over the
	 * cards next to this one.
	 */
	void renderBurst(Graphics2D graphics)
	{
		LevelUp up = levelUp == null ? null : levelUp.get();
		if (up == null || bounds.width <= 0)
		{
			return;
		}
		long now = System.currentTimeMillis();
		long since = now - up.getAt() - (up.isUnlock() ? FULL_MS : 0);
		if (since < 0 || since >= BURST_MS)
		{
			return;
		}
		double t = since / 1000.0;
		double life = since / (double) BURST_MS;
		long step = now / STEP_MS;

		Object antialias = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
		Color oldColor = graphics.getColor();

		if (since < 120)
		{
			// a white flash over the bar as it pops
			int grow = (int) (since / 30);
			graphics.setColor(new Color(255, 255, 255, (int) (230 * (1 - since / 120.0))));
			graphics.fillRect(bounds.x - grow, bounds.y - grow, bounds.width + grow * 2, bounds.height + grow * 2);
		}

		int count = up.isUnlock() ? 64 : 32;
		double speed = up.isUnlock() ? 1 : 0.7;
		for (int i = 0; i < count; i++)
		{
			// every frame works each pixel's path out again from the same seed, so nothing has to be kept
			Random random = new Random(mix(up.getAt() * 31 + i));
			double sx = bounds.x + random.nextDouble() * bounds.width;
			double sy = bounds.y + random.nextDouble() * bounds.height;
			double vx = (random.nextDouble() * 2 - 1) * 110 * speed;
			double vy = -(50 + random.nextDouble() * 170) * speed;
			int size = random.nextInt(4) == 0 ? 1 : 2 + random.nextInt(2);
			double fade = 0.55 + random.nextDouble() * 0.45;
			if (life > fade)
			{
				continue;
			}
			// near the end of their life the pixels blink out
			if (life > fade * 0.7 && ((step + i) & 1) == 0)
			{
				continue;
			}
			int px = (int) Math.round(sx + vx * t);
			int py = (int) Math.round(sy + vy * t + 0.5 * GRAVITY * t * t);
			Color c = pixels[(int) ((i + step) % pixels.length)];
			int alpha = (int) (255 * Math.min(1, (fade - life) / 0.2));
			graphics.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha));
			graphics.fillRect(px, py, size, size);
		}

		graphics.setColor(oldColor);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, antialias);
	}

	private static Color mix(Color a, Color b, double amount)
	{
		return new Color(
			(int) (a.getRed() + (b.getRed() - a.getRed()) * amount),
			(int) (a.getGreen() + (b.getGreen() - a.getGreen()) * amount),
			(int) (a.getBlue() + (b.getBlue() - a.getBlue()) * amount));
	}

	/** A steady random number from -1 to 1 for a time step, a different one per salt. */
	private static double noise(long step, int salt)
	{
		return (mix(step * 0x9E3779B97F4A7C15L + salt * 0xC2B2AE3D27D4EB4FL) & 0xFFFFFF) / (double) 0x800000 - 1;
	}

	/** Scrambles a number, as seeds next to each other give Random alike first values. */
	private static long mix(long h)
	{
		h ^= h >>> 31;
		h *= 0xBF58476D1CE4E5B9L;
		h ^= h >>> 29;
		h *= 0x94D049BB133111EBL;
		return h ^ h >>> 32;
	}

	@Override
	public Rectangle getBounds()
	{
		return bounds;
	}

	@Override
	public void setPreferredLocation(Point position)
	{
		location = position;
	}

	@Override
	public void setPreferredSize(Dimension dimension)
	{
		preferred = dimension;
	}
}

package com.nextunlocks;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.Text;

/**
 * Pinned skill tooltips and quest or diary cards, side by side on top of the chatbox. When the chatbox is collapsed they sit
 * on top of its buttons instead.
 */
class PinnedOverlay extends Overlay
{
	private static final int GAP = 2;

	private final Client client;
	private final NextUnlocksPlugin plugin;
	private final TooltipManager tooltipManager;

	/** Where each pinned card was drawn last frame, for the right-click menu: by Skill, or by wiki title. Client thread. */
	private final Map<Object, Rectangle> drawn = new HashMap<>();
	/** Measured size of the card last drawn for a pin; cards are drawn upward from the chatbox. */
	private final Map<Object, LayoutableRenderableEntity> measured = new HashMap<>();
	private final Map<Object, Dimension> sizes = new HashMap<>();

	@Inject
	PinnedOverlay(Client client, NextUnlocksPlugin plugin, TooltipManager tooltipManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.tooltipManager = tooltipManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		drawn.clear();
		if (plugin.getPinned().isEmpty() && plugin.getPinnedTasks().isEmpty())
		{
			return null;
		}
		Rectangle chat = chatTop();
		if (chat == null)
		{
			return null;
		}

		// skill cards first, then quests and diaries
		Map<Object, LayoutableRenderableEntity> cards = new LinkedHashMap<>();
		for (Skill skill : plugin.getPinned())
		{
			LayoutableRenderableEntity card = plugin.pinnedTooltip(skill);
			if (card != null)
			{
				cards.put(skill, card);
			}
		}
		for (String task : plugin.getPinnedTasks())
		{
			LayoutableRenderableEntity card = plugin.taskCard(task);
			if (card != null)
			{
				cards.put(task, card);
			}
		}

		// every skill card as tall as the tallest, so text-only ones line up with ones holding icons
		int skillHeight = 0;
		for (Map.Entry<Object, LayoutableRenderableEntity> e : cards.entrySet())
		{
			if (e.getKey() instanceof Skill)
			{
				skillHeight = Math.max(skillHeight, size(graphics, e.getKey(), e.getValue()).height);
			}
		}

		Map<Object, Integer> heights = new HashMap<>();
		int width = 0;
		int tallest = 0;
		for (Map.Entry<Object, LayoutableRenderableEntity> e : cards.entrySet())
		{
			Dimension size = size(graphics, e.getKey(), e.getValue());
			int height = e.getKey() instanceof Skill ? skillHeight : size.height;
			heights.put(e.getKey(), height);
			width += size.width + GAP;
			tallest = Math.max(tallest, height);
		}
		// split private chat shows just above the chatbox; go above its messages instead of over them
		int bottom = chat.y - GAP;
		Integer pmTop = privateChatTop(new Rectangle(chat.x, bottom - tallest, width, tallest));
		if (pmTop != null)
		{
			bottom = Math.min(bottom, pmTop - GAP);
		}

		net.runelite.api.Point mouse = client.getMouseCanvasPosition();
		int x = chat.x;
		for (Map.Entry<Object, LayoutableRenderableEntity> e : cards.entrySet())
		{
			LayoutableRenderableEntity card = e.getValue();
			int height = heights.get(e.getKey());
			Point location = new Point(x, bottom - height);
			card.setPreferredLocation(location);
			if (card instanceof TooltipBox)
			{
				((TooltipBox) card).setMinHeight(height);
			}
			Dimension rendered = card.render(graphics);
			if (card instanceof TooltipBox)
			{
				TooltipBox box = (TooltipBox) card;
				box.setMinHeight(0);
				// keep up with late changes, like item icons finishing loading
				sizes.put(e.getKey(), box.getLast());
				hover(box, mouse);
			}
			drawn.put(e.getKey(), new Rectangle(location, rendered));
			x += rendered.width + GAP;
		}
		// level-up bursts last, so the pixels fly over the cards beside them
		for (LayoutableRenderableEntity card : cards.values())
		{
			if (card instanceof TooltipBox)
			{
				((TooltipBox) card).bars().forEach(bar -> bar.renderBurst(graphics));
			}
		}
		return null;
	}

	/** Name the icon under the mouse, so icon-only cards still say what each one is. */
	private void hover(TooltipBox box, net.runelite.api.Point mouse)
	{
		if (mouse == null || !box.getBounds().contains(mouse.getX(), mouse.getY()))
		{
			return;
		}
		for (UnlockTileComponent tile : box.tiles())
		{
			if (tile.getName() != null && tile.getBounds().contains(mouse.getX(), mouse.getY()))
			{
				tooltipManager.add(new Tooltip(tile.getName()));
				return;
			}
		}
	}

	/** The pinned skill drawn under a canvas point, or null. Client thread. */
	Skill skillAt(int x, int y)
	{
		Object pin = pinAt(x, y);
		return pin instanceof Skill ? (Skill) pin : null;
	}

	/** The wiki title of the pinned quest or diary drawn under a canvas point, or null. Client thread. */
	String taskAt(int x, int y)
	{
		Object pin = pinAt(x, y);
		return pin instanceof String ? (String) pin : null;
	}

	private Object pinAt(int x, int y)
	{
		for (Map.Entry<Object, Rectangle> e : drawn.entrySet())
		{
			if (e.getValue().contains(x, y))
			{
				return e.getKey();
			}
		}
		return null;
	}

	/** The top of the split private messages that overlap the area, or null when none are showing there. */
	private Integer privateChatTop(Rectangle area)
	{
		Widget container = client.getWidget(InterfaceID.PmChat.CONTAINER);
		if (container == null || container.isHidden())
		{
			return null;
		}
		return top(container, area, null);
	}

	/** The lowest y of the message lines under the widget that overlap the area, or top when there are none. */
	private static Integer top(Widget widget, Rectangle area, Integer top)
	{
		for (Widget[] children : new Widget[][]{widget.getStaticChildren(), widget.getDynamicChildren(), widget.getNestedChildren()})
		{
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				if (child == null || child.isHidden())
				{
					continue;
				}
				String text = child.getText();
				Rectangle bounds = child.getBounds();
				if (text != null && !Text.removeTags(text).trim().isEmpty() && bounds.intersects(area))
				{
					top = top == null ? bounds.y : Math.min(top, bounds.y);
				}
				top = top(child, area, top);
			}
		}
		return top;
	}

	/** Bounds of the visible chat messages, or of the chat buttons when the chatbox is collapsed. */
	private Rectangle chatTop()
	{
		Widget area = client.getWidget(InterfaceID.Chatbox.CHATAREA);
		if (area != null && !area.isHidden())
		{
			return area.getBounds();
		}
		Widget controls = client.getWidget(InterfaceID.Chatbox.CONTROLS);
		if (controls != null && !controls.isHidden())
		{
			return controls.getBounds();
		}
		return null;
	}

	/** The tooltip's size, measured off-screen when it changed, so it can be placed above the chat before drawing. */
	private Dimension size(Graphics2D graphics, Object pin, LayoutableRenderableEntity tooltip)
	{
		Dimension size = sizes.get(pin);
		if (size == null || measured.get(pin) != tooltip)
		{
			BufferedImage scratch = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = scratch.createGraphics();
			g.setFont(graphics.getFont());
			g.setRenderingHints(graphics.getRenderingHints());
			tooltip.setPreferredLocation(new Point());
			// a new panel lays out from its previous frame, so the first pass is off; the second has settled
			tooltip.render(g);
			size = tooltip.render(g);
			g.dispose();
			measured.put(pin, tooltip);
			sizes.put(pin, size);
		}
		return size;
	}
}

package com.nextunlocks;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.function.ToIntFunction;
import lombok.AllArgsConstructor;
import lombok.Value;
import net.runelite.api.Skill;

/** One hard requirement of a pinned quest, diary or item, and whether the player meets it. */
@Value
@AllArgsConstructor
class Requirement
{
	/** The skill's name, "Quest points", "Combat level" or the quest's name. */
	String label;
	/** What the player has against what is needed, like 61/75; empty for quests. */
	String progress;
	boolean met;
	/** For an item's making level, the material it's for, like Ironwood logs; null when it's for the item itself. */
	String material;
	/** The material's item ID, for its icon; 0 when unknown. */
	int materialItem;
	/** The skill, for a skill level; null otherwise. */
	Skill skill;
	/** The quest's wiki title, for a quest; null otherwise. */
	String quest;

	Requirement(String label, String progress, boolean met)
	{
		this(label, progress, met, null, 0, null, null);
	}

	/** Progress shown for a requirement checked off by hand. */
	static final String DONE = "Done";

	/** The requirements with the ones whose label is in {@code checked} counted as met, unmet ones still first. */
	static List<Requirement> checkOff(List<Requirement> requirements, Set<String> checked)
	{
		if (checked.isEmpty())
		{
			return requirements;
		}
		List<Requirement> out = new ArrayList<>();
		for (Requirement r : requirements)
		{
			out.add(r.met || !checked.contains(r.label) ? r
				: new Requirement(r.label, DONE, true, r.material, r.materialItem, r.skill, r.quest));
		}
		out.sort(Comparator.comparing(Requirement::isMet));
		return out;
	}

	/**
	 * The task's requirements, unmet ones first. {@code level} gives the level that counts for each skill,
	 * {@code questDone} takes a quest's wiki title and {@code questName} turns one into the quest's name.
	 */
	static List<Requirement> check(Task task, ToIntFunction<Skill> level, int questPoints, int combat,
		Predicate<String> questDone, Function<String, String> questName)
	{
		return check(task, level, questPoints, combat, questDone, questName, true);
	}

	/**
	 * As above; for an item goal, {@code make} also counts the levels that make it from scratch, each skill needing the
	 * higher of its wield and making level.
	 */
	static List<Requirement> check(Task task, ToIntFunction<Skill> level, int questPoints, int combat,
		Predicate<String> questDone, Function<String, String> questName, boolean make)
	{
		Map<Skill, Integer> need = new LinkedHashMap<>(task.getSkills());
		Map<Skill, String> material = new HashMap<>();
		if (make)
		{
			for (Map.Entry<Skill, Integer> e : task.getMake().entrySet())
			{
				if (e.getValue() > need.getOrDefault(e.getKey(), 0))
				{
					need.put(e.getKey(), e.getValue());
					String what = task.getMadeFor().get(e.getKey());
					if (what != null && !what.equals(task.getName()))
					{
						material.put(e.getKey(), what);
					}
				}
			}
		}
		List<Requirement> out = new ArrayList<>();
		for (Map.Entry<Skill, Integer> e : need.entrySet())
		{
			int have = level.applyAsInt(e.getKey());
			String what = material.get(e.getKey());
			out.add(new Requirement(e.getKey().getName(), have + "/" + e.getValue(), have >= e.getValue(), what,
				what == null ? 0 : task.getMaterials().getOrDefault(e.getKey(), 0), e.getKey(), null));
		}
		if (task.getQuestPoints() > 0)
		{
			out.add(new Requirement("Quest points", questPoints + "/" + task.getQuestPoints(), questPoints >= task.getQuestPoints()));
		}
		if (task.getCombat() > 0)
		{
			out.add(new Requirement("Combat level", combat + "/" + task.getCombat(), combat >= task.getCombat()));
		}
		for (String quest : task.getQuests())
		{
			out.add(new Requirement(questName.apply(quest), "", questDone.test(quest), null, 0, null, quest));
		}
		// stable, so each group keeps the data's order
		out.sort(Comparator.comparing(Requirement::isMet));
		return out;
	}
}

package com.nextunlocks;

import java.awt.Rectangle;
import java.text.NumberFormat;
import java.util.ArrayList;
import java.util.HashMap;
