package com.nextunlocks;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Predicate;
import lombok.Value;
import net.runelite.api.Skill;

/** Player stats and settings handed from the client thread to the panel and tooltips. */
@Value
class Snapshot
{
	static final Snapshot EMPTY = new Snapshot(Collections.emptyMap(), Collections.emptyMap(), Collections.emptyMap(),
		u -> true, 5, Collections.emptySet(), Collections.emptySet(), Palette.DEFAULT,
		Collections.emptySet(), Collections.emptySet(), Collections.emptyList(), false, Collections.emptySet());

	/** Real levels. */
	Map<Skill, Integer> levels;
	Map<Skill, Integer> xp;
	/** Boosted levels, for skills whose boost counts; empty when boosts don't count. */
	Map<Skill, Integer> boosted;
	/** The members, quest and diary settings. */
	Predicate<Unlock> filter;
	int levelsAhead;
	/** Required quests the player hasn't finished; empty when unknown or not shown. */
	Set<Integer> unfinishedQuests;
	/** Hidden skill guide sections, as {@link #sectionKey} strings. */
	Set<String> hiddenSections;
	Palette palette;
	/** Required quests the player hasn't finished, whatever the grey-out setting; empty when unknown. */
	Set<Integer> questsToDo;
	/** Names of finished quests, as in {@link net.runelite.api.Quest#getName()}. */
	Set<String> finishedQuests;
	List<Goal> goals;
	/** Whether the panel lists what's one requirement away. */
	boolean almostThere;
	/** Wiki titles of the pinned quests and diaries. */
	Set<String> pinnedTasks;

	static String sectionKey(Skill skill, String section)
	{
		return skill.name() + ":" + section;
	}

	boolean isLoggedIn()
	{
		return !levels.isEmpty();
	}

	int level(Skill skill)
	{
		return levels.getOrDefault(skill, 1);
	}

	/** The level that counts for quests and diaries: the boost when boosts count. */
	int effectiveLevel(Skill skill)
	{
		return Math.max(level(skill), boosted.getOrDefault(skill, 0));
	}

	boolean isGoal(Skill skill, Unlock u)
	{
		return goals.stream().anyMatch(g -> g.is(skill, u));
	}

	int xp(Skill skill)
	{
		return xp.getOrDefault(skill, 0);
	}

	/** Whether the unlock is above the real level but within the current boost, and takes boosts. */
	boolean reachedByBoost(Skill skill, Unlock u)
	{
		return u.getLevel() > level(skill) && u.getLevel() <= boosted.getOrDefault(skill, 0) && UnlockRepository.boostable(skill, u);
	}

	/** Whether the unlock needs a quest the player hasn't finished. */
	boolean locked(Unlock u)
	{
		return u.getQuest() != null && unfinishedQuests.contains(u.getQuest());
	}

	boolean hidden(Skill skill, Unlock u)
	{
		return u.getSection() != null && hiddenSections.contains(sectionKey(skill, u.getSection()));
	}

	/** The settings' filter without hidden sections, for the unlocks still to come: boosts count as reached. */
	Predicate<Unlock> upcoming(Skill skill)
	{
		return u -> filter.test(u) && !hidden(skill, u) && !reachedByBoost(skill, u);
	}

	/** The settings' filter without hidden sections. */
	Predicate<Unlock> shown(Skill skill)
	{
		return u -> filter.test(u) && !hidden(skill, u);
	}
}

package com.nextunlocks;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Locale;
import java.util.stream.Collectors;
import lombok.Value;
import net.runelite.api.Skill;

/** An amount goal, like catching 500 lobsters: items counted as a skill makes or gathers them. */
@Value
class Tally
{
	/** Prefix of an amount goal's pin key, followed by its skill and item ID. */
	static final String KEY = "tally:";
	private static final String FIELD = "|";
	/** Most an amount goal can ask for. */
	static final int MAX_TARGET = 10_000_000;

	Skill skill;
	/** The item counted, unnoted. */
	int item;
	String name;
	int target;
	int count;

	String key()
	{
		return key(skill, item);
	}

	static String key(Skill skill, int item)
	{
		return KEY + skill.name() + ":" + item;
	}

	boolean isDone()
	{
		return count >= target;
	}

	Tally withCount(int count)
	{
		return new Tally(skill, item, name, target, Math.max(0, Math.min(MAX_TARGET, count)));
	}

	Tally withTarget(int target)
	{
		return new Tally(skill, item, name, target, count);
	}

	/** Whether the skill uses the item up, like logs burnt or bones buried, rather than making or gathering it. */
	static boolean usesUp(Skill skill)
	{
		return skill == Skill.FIREMAKING || skill == Skill.PRAYER || skill == Skill.CONSTRUCTION;
	}

	/** What the skill does to the item, for the card: "Catch", "Chop", "Burn". */
	static String verb(Skill skill)
	{
		switch (skill)
		{
			case FISHING:
			case HUNTER:
				return "Catch";
			case WOODCUTTING:
				return "Chop";
			case MINING:
				return "Mine";
			case COOKING:
				return "Cook";
			case SMITHING:
				return "Smith";
			case FLETCHING:
				return "Fletch";
			case HERBLORE:
				return "Mix";
			case FIREMAKING:
				return "Burn";
			case PRAYER:
				return "Bury";
			case FARMING:
				return "Harvest";
			case THIEVING:
				return "Steal";
			case CONSTRUCTION:
				return "Use";
			case CRAFTING:
			case RUNECRAFT:
				return "Craft";
			default:
				return "Make";
		}
	}

	/** The card's line, like "Catch 500 Lobster". */
	String goalText()
	{
		return verb(skill) + " " + String.format(Locale.ROOT, "%,d", target) + " " + name;
	}

	/** Parses an amount typed in the chatbox, like 500, 1,000, 2.5k or 1m; 0 for anything else. */
	static int parseAmount(String text)
	{
		String t = text == null ? "" : text.trim().toLowerCase(Locale.ROOT).replace(",", "");
		double multiplier = 1;
		if (t.endsWith("k") || t.endsWith("m"))
		{
			multiplier = t.endsWith("k") ? 1_000 : 1_000_000;
			t = t.substring(0, t.length() - 1);
		}
		try
		{
			double amount = Double.parseDouble(t) * multiplier;
			return amount >= 1 && amount <= MAX_TARGET ? (int) Math.round(amount) : 0;
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	/** Amount goals as kept in the config: SKILL|item|target|count|name, one per line; bad lines are skipped. */
	static List<Tally> parse(String text)
	{
		List<Tally> out = new ArrayList<>();
		for (String line : text == null ? new String[0] : text.split("\n"))
		{
			String[] parts = line.trim().split("\\|", 5);
			if (parts.length < 5 || parts[4].isEmpty())
			{
				continue;
			}
			try
			{
				int target = Integer.parseInt(parts[2]);
				if (target > 0)
				{
					out.add(new Tally(Skill.valueOf(parts[0]), Integer.parseInt(parts[1]), parts[4], target, 0)
						.withCount(Integer.parseInt(parts[3])));
				}
			}
			catch (IllegalArgumentException e)
			{
				// a skill that no longer exists, or a broken number
			}
		}
		return out;
	}

	static String format(Collection<Tally> tallies)
	{
		return tallies.stream()
			.map(t -> t.skill.name() + FIELD + t.item + FIELD + t.target + FIELD + t.count + FIELD + t.name.replace("\n", " "))
			.collect(Collectors.joining("\n"));
	}

	/**
	 * How much a tick's change in the item's inventory amount adds to the count: what arrived, or for a skill that uses
	 * items up, what went, and only while the skill is gaining xp.
	 */
	static int counted(Skill skill, int change, boolean gainingXp)
	{
		if (!gainingXp)
		{
			return 0;
		}
		return Math.max(0, usesUp(skill) ? -change : change);
	}
}

package com.nextunlocks;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import lombok.Value;
import net.runelite.api.Skill;

/** A quest, achievement diary or item that can be pinned, with its hard requirements. */
@Value
class Task
{
	/** The quest's name, as in {@link net.runelite.api.Quest#getName()}, or the diary's or item's title. */
	String name;
	/** The wiki page, which pins are kept by. */
	String wiki;
	boolean diary;
	Map<Skill, Integer> skills;
	int questPoints;
	int combat;
	/** Wiki titles of the quests needed first, the whole chain; for an item, the ones needed to wield or get it. */
	List<String> quests;
	/** For an item goal, the item ID its icon shows; 0 for quests and diaries. */
	int item;
	/** For an item goal, the levels that make it from scratch; {@link #skills} are the ones to wield or wear it. */
	Map<Skill, Integer> make;
	/** For each making level, what it makes: the item itself or a material, like Ironwood logs. */
	Map<Skill, String> madeFor;
	/** The item ID of each making level's material, for its icon; missing when unknown. */
	Map<Skill, Integer> materials;
	/** For a pinned skill guide unlock, like a spell or prayer, keyed {@link TaskRepository#UNLOCK}: its sprite, or 0. */
	int sprite;
	/** Whether this is a skill guide unlock, whose {@link #item} is only its icon. */
	boolean unlock;

	/** A quest or diary. */
	static Task of(String name, String wiki, boolean diary, Map<Skill, Integer> skills, int questPoints, int combat,
		List<String> quests)
	{
		return new Task(name, wiki, diary, skills, questPoints, combat, quests, 0, Collections.emptyMap(), Collections.emptyMap(),
			Collections.emptyMap(), 0, false);
	}

	/** An item goal; an unlock with an item icon isn't one. */
	boolean isItem()
	{
		return item > 0 && !unlock;
	}
}

